});

tRun("34 unknown command lists the valid ones", function () {
	tThrows(function () { tCall("rotate", { "vault.path": P_DB }); }, "Valid:");
});

tRun("35 typo in vault.mount never looks like success (read the result)", function () {
	var how;
	try {
		var st = tStatus(tCall("read", { "vault.path": "x", "vault.mount": "secrte" }));
		tAssert(st != 200, "unknown mount returned 200");
		how = "HTTP " + st + " - in Lookup mode this would look like 'no match'";
	} catch (ex) {
		if (String(ex).indexOf("unknown mount returned") >= 0) throw ex;
		how = "an error: " + ex;
	}
	task.logmsg("\tunknown mount gave " + how);
});

tRun("36 unwrap with a bogus wrapping token fails cleanly", function () {
	tThrows(function () {
		tCall("unwrap", { "vault.wrappingToken": "hvs.bogus-wrapping-token" });
	}, "unwrap failed");
});

tRun("37 unwrap returns the wrapped data, once only", function () {
	var tok = tWrap({ username: "svc_wrap", password: "Wrapped-Pw" });
	var r = tCall("unwrap", { "vault.wrappingToken": tok });
	tEq(tStatus(r), 200, "status");
	tEq(tVal(r, "username"), "svc_wrap", "username");
	tEq(tVal(r, "password"), "Wrapped-Pw", "password");
	tThrows(function () {
		tCall("unwrap", { "vault.wrappingToken": tok });
