// Delete: offboarding an application
// =====================================================================
tRun("45 soft delete hides the latest version", function () {
	tEq(tStatus(tCall("delete", { "vault.path": P_DB })), 204, "status");
	tEq(tStatus(tCall("read", { "vault.path": P_DB })), 404, "read after delete");
});

tRun("46 soft delete keeps older versions and metadata", function () {
	tEq(tVal(tCall("read", { "vault.path": P_DB, "vault.version": 3 }), "password"), "Replaced-Pw-3", "v3 password");
	tEq(tStatus(tCall("metadataRead", { "vault.path": P_DB })), 200, "metadata");
});

tRun("47 metadataDelete removes the secret and all versions", function () {
	tEq(tStatus(tCall("metadataDelete", { "vault.path": P_DB })), 204, "status");
	tEq(tStatus(tCall("metadataRead", { "vault.path": P_DB })), 404, "metadata after delete");
	tEq(tStatus(tCall("read", { "vault.path": P_DB, "vault.version": 1 })), 404, "v1 after delete");
});

