tRun("50 AddOnly: putEntry writes a new secret from the Output Map", function () {
	entry = tEntry({ "vault.path": P_MODE, "vault.cas": 0, username: "svc_hr", password: "Hr-Pw-1", email: "hr@example.local" });
	putEntry();
	tEq(tVal(tCall("read", { "vault.path": P_MODE }), "vault.version"), 1, "version");
});

tRun("51 Lookup: findEntry with Link Criteria finds the secret", function () {
	tSearch(P_MODE);
	entry = tEntry({});
	findEntry();
	tAssert(result.status != 0, "reported as no match");
	tEq(tVal(entry, "username"), "svc_hr", "username");
	tEq(tVal(entry, "vault.version"), 1, "version");
});

tRun("52 Lookup: a missing secret goes to On No Match", function () {
	tSearch(P_NONE);
	entry = tEntry({});
	findEntry();
	tEq(result.status, 0, "result status");
});

tRun("53 Update (patch): match found, other keys kept", function () {
	tAssert(tUpdate(P_MODE, { password: "Hr-Pw-2" }), "no match");
	var r = tCall("read", { "vault.path": P_MODE });
	tEq(tVal(r, "password"), "Hr-Pw-2", "password");
	tEq(tVal(r, "email"), "hr@example.local", "email kept");
});

tRun("54 Update (replace): exactly the mapped keys are written", function () {
	tWithMethod("replace", function () {
		tAssert(tUpdate(P_MODE, { username: "svc_hr", password: "Hr-Pw-3" }), "no match");
	});
	var r = tCall("read", { "vault.path": P_MODE });
	tEq(tVal(r, "password"), "Hr-Pw-3", "password");
	tAssert(tVal(r, "email") == null, "email should be gone");
});

tRun("55 Delete (soft): deleteEntry after a match, still recoverable", function () {
	tAssert(tDelete(P_MODE), "no match");
	tEq(tStatus(tCall("read", { "vault.path": P_MODE })), 404, "read after delete");
	tEq(tStatus(tCall("metadataRead", { "vault.path": P_MODE })), 200, "metadata kept");
});

tRun("56 Delete (permanent): a soft-deleted secret is no match, a live one is removed with all versions", function () {
	tWithCfg({ deleteMode: "permanent" }, function () {
		// Lookup does not find a soft-deleted secret, so Delete mode never reaches it
		tAssert(!tDelete(P_MODE), "the soft-deleted secret matched");
		tEq(tStatus(tCall("metadataRead", { "vault.path": P_MODE })), 200, "metadata still there");

		// Write it again, and Delete mode can remove it for good
		tCall("write", { "vault.path": P_MODE, username: "svc_hr", password: "Hr-Pw-4" });
		tAssert(tDelete(P_MODE), "no match");
	});
	tEq(tStatus(tCall("metadataRead", { "vault.path": P_MODE })), 404, "metadata after delete");
});

tRun("57 Link Criteria: vault.mount, path by another name, and no path at all", function () {
	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }, { name: "vault.path", value: P_MULTI }]);
	entry = tEntry({});
	findEntry();
	tAssert(result.status != 0, "vault.mount + vault.path: no match");
	tEq(tVal(entry, "vault.mount"), cfg.kvMount, "vault.mount");

	// Without vault.path, the first criterion that is not vault.mount is the path
	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }, { name: "secretPath", value: P_MULTI }]);
	entry = tEntry({});
	findEntry();
	tAssert(result.status != 0, "path under another name: no match");
	tEq(tVal(entry, "vault.path"), P_MULTI, "vault.path");

	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }]);
	entry = tEntry({});
	tThrows(findEntry, "Link Criteria must give the secret path");
});

tRun("58 Update, match: vault.path in the entry wins over the Link Criteria", function () {
	tAssert(tUpdate(P_MULTI, { "vault.path": P_ODD, owner: "from-entry" }), "no match");
	tEq(tVal(tCall("read", { "vault.path": P_ODD }), "owner"), "from-entry", "owner on the entry's path");
	tAssert(tVal(tCall("read", { "vault.path": P_MULTI }), "owner") != "from-entry", "the Link Criteria path was written");
});

tRun("59 Update, no match: putEntry writes the entry, the Link Criteria path is left alone", function () {
	tAssert(!tUpdate(P_NONE, { "vault.path": P_MODE, "vault.cas": 0, owner: "added-on-no-match" }), "a missing secret matched");
	var r = tCall("read", { "vault.path": P_MODE });
	tEq(tVal(r, "owner"), "added-on-no-match", "owner");
	tEq(tVal(r, "vault.version"), 1, "version");
	tEq(tStatus(tCall("read", { "vault.path": P_NONE })), 404, "the Link Criteria path was not written");
});

// =====================================================================
// Token lifecycle: long-running AssemblyLines
// =====================================================================
tRun("60 token close to expiry is renewed (or re-logged) before use", function () {
	if (tokenExpiresAt == 0) {
		task.logmsg("\tskipped: token never expires");
		return;
	}
	tokenExpiresAt = now() + 30000;		// pretend it expires in 30 s
	var before = tokenExpiresAt;
	tCall("lookupSelf");
	tAssert(tokenExpiresAt > before + 60000, "expiry was not pushed out");
});

tRun("61 revoked token: next call logs in again on its own", function () {
	if (cfg.authMethod == "token") {
		task.logmsg("\tskipped: authMethod=token cannot log in again");
		return;
	}
	var old = clientToken;
	vaultRequest("POST", "/v1/auth/token/revoke-self", null, {});
	var r = tCall("read", { "vault.path": P_MULTI });
	tEq(tStatus(r), 200, "status after re-login");
	tAssert(clientToken != old, "token was not replaced");
});

tRun("62 the urlConnection transport works too, UTF-8 included", function () {
	var saved = httpClient;
	if (saved == null) {
		task.logmsg("\tskipped: already running on urlConnection (TLS stores configured)");
		return;
	}
	httpClient = null;			// vaultRequest() then sends with HttpURLConnection
	try {
		tCall("write", { "vault.path": P_ODD, note: "rømmegrøt via urlConnection" });
		tEq(tVal(tCall("read", { "vault.path": P_ODD }), "note"), "rømmegrøt via urlConnection", "read via urlConnection");
	} finally {
		httpClient = saved;
	}
	tEq(tVal(tCall("read", { "vault.path": P_ODD }), "note"), "rømmegrøt via urlConnection", "read via httpClient");
});

// =====================================================================
// Iterator mode: walking a KV folder
// =====================================================================
tRun("70 Iterator: one entry per secret, depth first, soft-deleted skipped", function () {
	for (var i = 0; i < T_ITER_KEYS.length; i++) {
		var k = T_ITER_KEYS[i];
		if (k == "typed") {
			tCall("write", { "vault.path": P_ITER + "/typed", "vault.json": T_TYPED });
		} else {
			tCall("write", { "vault.path": P_ITER + "/" + k, k: k });
		}
	}
	tCall("delete", { "vault.path": P_ITER + "/gone" });

	var found = tIterate({ iteratorPath: P_ITER });
	// P_ITER's own secrets first (gone skipped), then sub/, then sub/deep/
	tEq(tColumn(found, "vault.relativePath").join(","), "a,sub,typed,sub/b,sub/deep/c", "relativePath order");
	tEq(tColumn(found, "vault.path")[0], P_ITER + "/a", "vault.path is the full path");
});

tRun("71 Iterator: each entry is what Lookup returns, plus vault.relativePath", function () {
	var it = tFind(tIterate({ iteratorPath: P_ITER }), "vault.relativePath", "sub/b");
	tAssert(it != null, "sub/b not returned");
	var lk = tLookup(P_ITER + "/sub/b");
	tAssert(lk != null, "Lookup found nothing");
	var names = ["k", "vault.path", "vault.mount", "vault.name", "vault.folder", "vault.version", "vault.created_time", "vault.status"];
	for (var i = 0; i < names.length; i++) {
		tEq(tVal(it, names[i]), tVal(lk, names[i]), names[i]);
	}
	tEq(tVal(it, "vault.name"), "b", "vault.name");
	tEq(tVal(it, "vault.folder"), P_ITER + "/sub", "vault.folder");
	tEq(tVal(it, "vault.mount"), cfg.kvMount, "vault.mount");
	tAssert(tVal(lk, "vault.relativePath") == null, "Lookup has no vault.relativePath");
});

