tRun("60 token close to expiry is renewed (or re-logged) before use", function () {
	if (tokenExpiresAt == 0) {
		task.logmsg("\tskipped: token never expires");
		return;
	}
	tokenExpiresAt = now() + 30000;		// pretend it expires in 30 s
	var before = tokenExpiresAt;
	tCall("lookupSelf");
	tAssert(tokenExpiresAt > before + 60000, "expiry was not pushed out");
});

tRun("61 revoked token: next call logs in again on its own", function () {
	if (cfg.authMethod == "token") {
		task.logmsg("\tskipped: authMethod=token cannot log in again");
		return;
	}
	var old = clientToken;
	vaultRequest("POST", "/v1/auth/token/revoke-self", null, {});
	var r = tCall("read", { "vault.path": P_MULTI });
	tEq(tStatus(r), 200, "status after re-login");
	tAssert(clientToken != old, "token was not replaced");
});

tRun("62 the urlConnection transport works too, UTF-8 included", function () {
	var saved = httpClient;
	if (saved == null) {
		task.logmsg("\tskipped: already running on urlConnection (TLS stores configured)");
		return;
	}
	httpClient = null;			// vaultRequest() then sends with HttpURLConnection
	try {
		tCall("write", { "vault.path": P_ODD, note: "rømmegrøt via urlConnection" });
		tEq(tVal(tCall("read", { "vault.path": P_ODD }), "note"), "rømmegrøt via urlConnection", "read via urlConnection");
	} finally {
		httpClient = saved;
	}
	tEq(tVal(tCall("read", { "vault.path": P_ODD }), "note"), "rømmegrøt via urlConnection", "read via httpClient");
});

// =====================================================================
// Iterator mode: walking a KV folder
// =====================================================================
tRun("70 Iterator: one entry per secret, depth first, soft-deleted skipped", function () {
	for (var i = 0; i < T_ITER_KEYS.length; i++) {
		var k = T_ITER_KEYS[i];
		if (k == "typed") {
			tCall("write", { "vault.path": P_ITER + "/typed", "vault.json": T_TYPED });
		} else {
			tCall("write", { "vault.path": P_ITER + "/" + k, k: k });
		}
	}
	tCall("delete", { "vault.path": P_ITER + "/gone" });

	var found = tIterate({ iteratorPath: P_ITER });
	// P_ITER's own secrets first (gone skipped), then sub/, then sub/deep/
	tEq(tColumn(found, "vault.relativePath").join(","), "a,sub,typed,sub/b,sub/deep/c", "relativePath order");
	tEq(tColumn(found, "vault.path")[0], P_ITER + "/a", "vault.path is the full path");
});

tRun("71 Iterator: each entry is what Lookup returns, plus vault.relativePath", function () {
	var it = tFind(tIterate({ iteratorPath: P_ITER }), "vault.relativePath", "sub/b");
	tAssert(it != null, "sub/b not returned");
	var lk = tLookup(P_ITER + "/sub/b");
	tAssert(lk != null, "Lookup found nothing");
	var names = ["k", "vault.path", "vault.mount", "vault.name", "vault.folder", "vault.version", "vault.created_time", "vault.status"];
	for (var i = 0; i < names.length; i++) {
		tEq(tVal(it, names[i]), tVal(lk, names[i]), names[i]);
	}
	tEq(tVal(it, "vault.name"), "b", "vault.name");
	tEq(tVal(it, "vault.folder"), P_ITER + "/sub", "vault.folder");
	tEq(tVal(it, "vault.mount"), cfg.kvMount, "vault.mount");
	tAssert(tVal(lk, "vault.relativePath") == null, "Lookup has no vault.relativePath");
});

tRun("72 Iterator: iteratorRecursive=false stays in the folder", function () {
