		tEq(tSecretKeys(found[i]).length, 0, "secret keys on " + tVal(found[i], "vault.path"));
	}
});

tRun("74 Iterator: an empty or unknown folder gives no entries and no error", function () {
	tEq(tIterate({ iteratorPath: P_ITER + "/nope" }).length, 0, "entry count");
});

tRun("75 vault.json keeps numbers, booleans and nested objects", function () {
	var e = tFind(tIterate({ iteratorPath: P_ITER, kvJson: "true" }), "vault.name", "typed");
	tAssert(e != null, "typed not returned");
	var d = fromJson(tVal(e, "vault.json"));
	tAssert(d.port === 5432, "port is not the number 5432: " + d.port);
	tAssert(d.tls === true, "tls is not the boolean true: " + d.tls);
	tEq(d.opts.pool, 5, "opts.pool");
	tEq(d.opts.hosts.length, 2, "opts.hosts count");
	// The plain attributes show the same secret as strings and JSON text
	tEq(tVal(e, "port"), "5432", "plain port");
	tEq(fromJson(tVal(e, "opts")).pool, 5, "plain opts is JSON text");
	tAssert(tVal(tCall("read", { "vault.path": P_ITER + "/typed" }), "vault.json") == null, "vault.json without kvJson");
});

tRun("76 Iterator -> AddOnly with vault.json copies the tree exactly", function () {
	var src = tIterate({ iteratorPath: P_ITER, kvJson: "true" });
	for (var i = 0; i < src.length; i++) {
		tAdd({ "vault.path": P_COPY + "/" + tVal(src[i], "vault.relativePath"), "vault.cas": 0, "vault.json": tVal(src[i], "vault.json") });
	}
	var dst = tIterate({ iteratorPath: P_COPY, kvJson: "true" });
	tEq(tColumn(dst, "vault.relativePath").join(","), tColumn(src, "vault.relativePath").join(","), "copied paths");
	for (var j = 0; j < src.length; j++) {
		tEq(toJson(fromJson(tVal(dst[j], "vault.json"))), toJson(fromJson(tVal(src[j], "vault.json"))), "data of " + tVal(src[j], "vault.relativePath"));
	}
});

tRun("77 vault.json wins over plain attributes, and must be an object", function () {
	tCall("write", { "vault.path": P_COPY + "/a", "vault.json": "{\"k\": \"from-json\"}", k: "from-attribute", extra: "ignored" });
	var r = tCall("read", { "vault.path": P_COPY + "/a" });
	tEq(tVal(r, "k"), "from-json", "k");
	tEq(tSecretKeys(r).join(","), "k", "stored keys");
	tThrows(function () {
		tCall("write", { "vault.path": P_COPY + "/a", "vault.json": "[1, 2]" });
	}, "must hold a JSON object");
	tEq(tVal(tCall("read", { "vault.path": P_COPY + "/a" }), "k"), "from-json", "unchanged after the bad write");
});

tRun("78 patch with vault.json: typed values, top-level keys merged", function () {
	tCall("patch", { "vault.path": P_ITER + "/typed", "vault.json": "{\"port\": 6543, \"opts\": {\"pool\": 9}}" });
	var d = tWithKvJson(function () {
		return fromJson(tVal(tCall("read", { "vault.path": P_ITER + "/typed" }), "vault.json"));
	});
	tAssert(d.port === 6543, "port is not the number 6543: " + d.port);
	tAssert(d.tls === true, "tls not kept: " + d.tls);
	tEq(d.user, "svc_tdi", "user kept");
	// Merging is per top-level key, as for plain attributes: opts is replaced as a whole
	tEq(toJson(d.opts), "{\"pool\":9}", "opts");
});

