tRun("80 capabilities: policy allows tdi-test-* policies and identity, not its own policy", function () {
	var checks = [
		["sys/policies/acl", ["list"]],
		["sys/policies/acl/" + N_POL, ["create", "read", "update", "delete"]],
		["identity/entity/name", ["list"]],
		["identity/entity/name/" + N_ALICE, ["create", "read", "update", "delete"]],
		["identity/entity-alias", ["create", "update"]],
		["identity/group/name", ["list"]],
		["identity/group/name/" + N_TEAM, ["create", "read", "update", "delete"]],
		["identity/group-alias", ["create", "update"]],
		["sys/auth", ["read"]]
	];
	var missing = [];
	for (var i = 0; i < checks.length; i++) {
		var caps = tVals(tCall("capabilities", { "vault.apiPath": checks[i][0] }), "vault.capabilities");
		if (tHas(caps, "root")) {
			task.logmsg("\troot token - policy not really tested");
			return;
		}
		for (var j = 0; j < checks[i][1].length; j++) {
			if (!tHas(caps, checks[i][1][j])) {
				missing.push(checks[i][0] + ":" + checks[i][1][j]);
			}
		}
	}
	tAssert(missing.length == 0, "policy is missing " + missing.join(", ") + ". Run the updated setup.sh");

	// The connector must not be able to rewrite the policy it runs with
	var own = tVals(tCall("capabilities", { "vault.apiPath": "sys/policies/acl/tdi-test" }), "vault.capabilities");
	tAssert(!tHas(own, "update") && !tHas(own, "create"), "the connector can rewrite its own policy: " + own.join(", "));
});

