// =====================================================================
// Cleanup, then terminate
// =====================================================================
var tLeftovers = [P_DB, P_CTL, P_MULTI, P_ODD, P_MODE];
for (var tk = 0; tk < T_ITER_KEYS.length; tk++) {
	tLeftovers.push(P_ITER + "/" + T_ITER_KEYS[tk]);
	tLeftovers.push(P_COPY + "/" + T_ITER_KEYS[tk]);
}
for (var ti = 0; ti < tLeftovers.length; ti++) {
	try {
		tCall("metadataDelete", { "vault.path": tLeftovers[ti] });
	} catch (ex) {
		task.logmsg("cleanup " + tLeftovers[ti] + ": " + ex);
	}
}

// Groups first, since they refer to entities. Deleting one that is already gone is fine.
var tIdLeftovers = [["group", N_ALL], ["group", N_TEAM], ["group", N_EXT], ["entity", N_ALICE], ["entity", N_BOB], ["policy", N_POL]];
for (var tj = 0; tj < tIdLeftovers.length; tj++) {
	try {
		handlerFor(tIdLeftovers[tj][0]).remove(tIdLeftovers[tj][1], cfg.kvMount, system.newEntry());
	} catch (ex) {
		task.logmsg("cleanup " + tIdLeftovers[tj][0] + " " + tIdLeftovers[tj][1] + ": " + ex);
	}
}

tRun("120 cleanup left nothing behind", function () {
	tEq(tStatus(tCall("list", { "vault.path": TEST_ROOT })), 404, "list of the test folder");
});

tRun("121 cleanup left no test policy, entity or group", function () {
	var types = ["policy", "entity", "group"];
	var left = [];
	for (var i = 0; i < types.length; i++) {
		var names = tNames(types[i]);
		for (var j = 0; j < names.length; j++) {
			if (names[j].indexOf(T_ID) == 0) {
				left.push(types[i] + " " + names[j]);
			}
		}
	}
	tAssert(left.length == 0, "left behind: " + left.join(", "));
});

tRun("122 terminate revokes the connector's own token", function () {
	var tok = clientToken;
	terminate();
	tAssert(clientToken == null, "clientToken not cleared");
	if (cfg.authMethod == "token") {
		return;
	}
	var r = vaultRequest("GET", "/v1/auth/token/lookup-self", null, { token: tok });
	tEq(r.status, 403, "old token after terminate");
});

task.logmsg("==== " + tPass + " passed, " + tFail + " failed");

// =============================================================================
// SPOOFLIB — Test harness for TDI Connector scripting and testing
// =============================================================================
// CHANGELOG:
// 20261005 - Initial version for Kafka connector
// =============================================================================


// =============================================================================
// NAME RESOLUTION
// Lowercases the requested name and verifies it exists in testParams.
// Kafka params have no legacy aliases — direct lookup is sufficient.
// Returns null if unrecognised so getControl() can return a sentinel control.
// =============================================================================

function __spoof_resolveParam(pname) {
    var lower = String(pname).toLowerCase();
    return (typeof testParams[lower] !== 'undefined') ? lower : null;
}


// =============================================================================
// CONTROL FACTORY
// Simulates a TDI Configuration Editor form field.
// Reads label, tooltip and value from the testParams parameter object.
// getText() is what form and connector scripts call to read a value.
// Mutating calls (setText, select) log and update local state so subsequent
// getText() calls reflect any changes made by the script under test.
// =============================================================================

function __spoof_control(paramName, val) {

    this.paramName = paramName;
    this.val       = (val !== undefined && val !== null) ? val : '';

    this.formatLog = function(msg) {
        return '[' + this.paramName + '] ' + msg;
    };

    this.getText = function() {
        return connector.getParam(paramName);
    };

    this.setText = function(newVal) {
        main.logmsg(this.formatLog('setText: ' + newVal));
        this.val = newVal;
    };

    this.getSelection = function() {
        return (typeof this.val === 'boolean') ? this.val : false;
    };

    this.setVisible = function(visible) {
        main.logmsg(this.formatLog(visible ? 'VISIBLE' : 'hidden'));
    };

    this.setEnabled = function(enabled) {
        main.logmsg(this.formatLog(enabled ? 'ENABLED' : 'disabled'));
    };

    this.removeAll       = function()      { main.logmsg(this.formatLog('removeAll')); };
    this.add             = function(item)  { main.logmsg(this.formatLog('add: ' + item)); };
    this.select          = function(index) { main.logmsg(this.formatLog('select: ' + index)); this.val = index; };
    this.getSelectedItem = function()      { return this.val; };
    this.getItemCount    = function()      { return 0; };

    return this;
}


// =============================================================================
// FORM OBJECT
// Simulates the form object available in TDI Form Init and Event scripts.
// getControl() resolves names via __spoof_resolveParam and passes the full
// parameter object to __spoof_control so label, tooltip and value are all
// available. Unknown names return a sentinel control and log a warning.
// =============================================================================

form = {

	getControl: function(pname) {
//	    var canonical = __spoof_resolveParam(pname);
//	    if (canonical === null) {
//	        main.logmsg('SPOOFLIB WARNING: unknown parameter "' + pname + '"');
//	        return __spoof_control(String(pname), '*Invalid param: ' + pname + '*');
//	    }
	    return __spoof_control(canonical, testParams[canonical]);
	},
    alert:           function(msg) { main.logmsg('FORM ALERT: ' + msg); },
    setWaitCursor:   function()    { main.logmsg('!! WAIT CURSOR !!'); },
    setNormalCursor: function()    { main.logmsg('.. Normal cursor ..'); }
};

/*
// =============================================================================
// CONNECTOR OBJECT
// Simulates the Script Connector interface available in both Connector scripts
// and Form scripts. getParam() delegates to form.getControl() so both surfaces
// read from testParams via the same resolution path.
// addFindEntry() logs the entry so findEntry() results are visible in test output.
// =============================================================================

connector = {

    getParam: function(pname) {
        return form.getControl(pname).getText();
    },

    getName: function() {
        return 'KafkaConnector-Test';
    },

    addFindEntry: function(e) {
        main.logmsg('addFindEntry: ' + e);
    }
};
*/

// =============================================================================
// CONFIG / PARENT STUBS
// config.getMode() is the correct TDI call for reading the connector operating
// mode from within a Connector script. __tdyModeOverride is set in the test
// AL script before calling initialize(), allowing the mode to be controlled
// per test run without touching testParams or spooflib.
// Falls back to 'Iterator' if __tdyModeOverride is not defined.
// =============================================================================

config = {

    getParent: function() { return parent; },

    getMode: function() {
        return (typeof __tdyModeOverride !== 'undefined')
            ? __tdyModeOverride
            : 'Iterator';
    }
};

parent = {
    getMode: function() { return config.getMode(); }
};


// =============================================================================
// RESULT OBJECT
// Simulates the result object available in findEntry().
// Logs status changes with human-readable labels.
// =============================================================================

result = {
    _status: 0,

    setStatus: function(s) {
        var labels = ['not found', 'found', 'multiple found'];
        this._status = s;
        main.logmsg('result.setStatus: ' + s + ' (' + (labels[s] || 'unknown') + ')');
    },

    getStatus: function() {
        return this._status;
    }
};


// =============================================================================
// MISCELLANEOUS
// =============================================================================

function alert(msg) { main.logmsg('ALERT: ' + msg); }

// Default value. Must be set in test script to initialize correctly
__tdyModeOverride = "Iterator";

// The predefined entry variable
var entry = system.newEntry();

// =====================================================================
// HashiCorp Vault Connector for TDI 7.2 (Script Connector)
// Version 0.4.2 (draft) - also in vault_VERSION, which is logged at startup
//
// History (new functionality: next 0.x, corrections: next 0.x.n)
//	2026-09-28	0.1	First draft: KV v2 read, write, list and delete as CallReply commands, AppRole login
//	2026-09-28	0.2	objectType, kvSecret in all standard modes, patch with CAS, health and capability
//				checks, AppRole response wrapping, cert auth, HTTP Client Connector transport
//	2026-10-10	0.2.1	Native JavaScript JSON (toJson/fromJson), instanceof Array, parameters read by name
//	2026-10-15	0.3	objectTypes policy, entity (with aliases) and group (internal and external)
//	2026-10-16	0.3.1	keysOf() sorted, so "Valid: ..." messages are the same on every run
//	2026-10-16	0.4	Iterator mode for every objectType, vault.name, vault.folder, vault.relativePath,
//				vault.json and kvJson for lossless copies
//	2026-10-17	0.4.1	Version logged at startup, config dump removed from loadConfig()
//	2026-10-17	0.4.2	Parameters with opt checked at startup, requiredCapabilities gets opt (multi-select)
//
// Available
//	Phase 1	KV v2 secrets in all standard modes. Production auth: AppRole with
//		response wrapping, TLS client certificates. Startup health and
//		capability checks.
//	Phase 2	Iterator mode for every objectType. One entry per object, with
//		vault.path as its unique name, like $dn for LDAP.
//	Phase 3	ACL policies, identity entities (with aliases) and identity groups
//		(internal and external) in the standard modes.
// Planned
//	Phase 4	dbCreds: dynamic credentials from the database secrets engine,
//		with lease renewal, and revoke on terminate.
// =====================================================================
//
// VAULT TERMS AS USED BY THIS CONNECTOR
// TDI concepts keep their usual meaning; this shows what they map to in Vault.
//
//	Entry			One secret: the key/value pairs stored at one path.
//				Or one policy, entity or group (see objectType).
//	Attribute		One key in the secret. Multi-valued attributes are stored
//				as JSON arrays and read back as multi-valued.
//	vault.* attributes	Control data and Vault metadata. Never stored in the secret.
//	vault.path		Path of the secret under its mount, e.g. apps/tdi/db,
//				or the name of a policy, entity or group.
//				Plays the role $dn plays for LDAP: map it in the Output
//				Map and use it in Link Criteria. In Iterator mode it is
//				the unique attribute for the Delta engine.
//	vault.name, vault.folder	The last part of a secret's path, and the path
//				of the folder it is in: apps/tdi/db -> db, apps/tdi.
//	vault.relativePath	Iterator mode: the path below iteratorPath. With
//				iteratorPath apps/tdi, apps/tdi/db -> db. Use it to
//				copy a tree to another place: vault.path = "new/" + it.
//	vault.json		The whole secret as one JSON object. Plain attributes
//				hold nested objects as JSON text and numbers and booleans
//				as strings; vault.json keeps them as they are. Read when
//				kvJson = true. When vault.json is mapped on a write, it
//				is the secret, and plain attributes are ignored.
//	Mount (kvMount)		Where a secrets engine is enabled, e.g. "secret".
//				Override per entry with vault.mount, or in Link Criteria
//				with vault.mount equals <mount>.
//	KV v2			Vault's versioned key/value secrets engine. Every write
//				creates a new version (vault.version).
//	CAS (vault.cas)		Check-and-set: a write only succeeds if the secret is
//				still at the given version. 0 = only create, never overwrite.
//	Soft delete		Hides the latest version. Recoverable with undelete.
//				The Iterator skips secrets whose latest version is deleted.
//	metadataDelete		Removes the secret and all its versions permanently.
//	Auth method		How the connector logs in: approle, cert or token.
//	AppRole			Machine login: role_id (like a user name) plus secret_id
//				(like a password).
//	Response wrapping	The secret_id is handed over inside a single-use wrapping
//				token. The connector verifies and unwraps it at login, so
//				the real secret_id is never stored in configuration.
//	Cert auth		Login with a TLS client certificate (mTLS) from a keystore.
//				No password or secret_id at all.
//	Token, TTL		Login returns a client token with a time-to-live. The
//				connector renews it, and logs in again when needed.
//	Policy, capabilities	Policies grant capabilities (read, create, update, delete,
//				list) on paths. capabilityCheckPath verifies them at startup.
//				With objectType=policy, policies are also the entries:
//				vault.path is the name, vault.policy the policy text.
//	Entity			Vault's identity for one person or machine, across all the
//				ways it logs in. Policies on the entity apply to all its tokens.
//	Alias			Links an entity to one login in one auth method, written as
//				<auth mount>:<login name>, e.g. ldap:jdoe. One per auth mount.
//	Group			Policies on a group apply to all its members.
//				Internal group: members are set by name (vault.members).
//				External group: members come from the auth method, through
//				one alias, e.g. ldap:vault-admins.
//	Metadata		Free-form string key/value pairs on an entity or group.
//				Plain attributes (not vault.*) are the metadata.
//	Namespace		Vault Enterprise/HCP tenant, sent as X-Vault-Namespace.
//	Sealed			Vault is running but locked. The startup health check
//				reports this instead of a confusing login error.
//
// CAPABILITIES THE CONNECTOR'S OWN VAULT POLICY NEEDS, PER objectType
// (only for the operations you use; list needs the path without /*)
//	kvSecret	{mount}/data/*			read, create, update, delete
//		{mount}/metadata/*			list (Iterator, list), read (metadataRead),
//							delete (deleteMode=permanent)
//		Iterator: list on the iteratorPath folder and every folder below it
//	policy	sys/policies/acl, sys/policies/acl/*	read, create, update, delete, list
//		Note: writing policies is admin-level power. Whoever can do it
//		can grant itself anything, so protect this connector's credentials.
//	entity	identity/entity/name, .../name/*	read, create, update, delete, list
//		identity/entity-alias, .../entity-alias/id/*	create, update, delete
//		sys/auth				read (resolves the mount in an alias)
//	group	identity/group/name, .../name/*		read, create, update, delete, list
//		identity/entity/name/*, identity/entity/id/*,
//		identity/group/id/*			read (member names <-> IDs)
//		identity/group-alias, .../group-alias/id/*	create, update, delete
//		sys/auth				read (resolves the mount in an alias)
//	Iterator with readData=true reads every listed object, so the policy
//	needs read on all of them. A 403 on one stops the run with its name.
// =====================================================================

var vault_params = {

	// --- Connector parameters, read with connector.getParam() ----------------
	// param	the configuration parameter name (form field name)
	// def		used when the parameter is empty or missing
	// opt		the valid values: a drop-down. Checked at startup, ignoring case
	// multi	true = a comma-separated list of opt values: a multi-select
	connection: {
		// Vault server
		vaultUrl:				{ param: "vaultUrl",					def: "http://10.211.55.2:8200" },
		namespace:				{ param: "vaultNamespace",				def: "" },		// Enterprise/HCP only
		timeoutMs:				{ param: "timeoutMs",					def: "10000" },		// urlConnection transport only
		httpTransport:			{ param: "httpTransport",				def: "auto",	opt: ["auto", "httpClient", "urlConnection"] },		// auto | httpClient | urlConnection
													// auto = HTTP Client Connector, unless this
													// connector has its own TLS stores (cert auth)

		// What the standard modes work on
		objectType:				{ param: "objectType",					def: "kvSecret",	opt: ["kvSecret", "policy", "entity", "group"] },	// see objectTypes
		kvMount:				{ param: "kvMount",						def: "secret" },	// KV v2 mount path
		updateMethod:			{ param: "updateMethod",				def: "patch",	opt: ["patch", "replace"] },		// Update mode: patch | replace (see attributes)
		deleteMode:				{ param: "deleteMode",					def: "soft",	opt: ["soft", "permanent"] },		// kvSecret only: soft | permanent
		kvJson:					{ param: "kvJson",						def: "false",	opt: ["true", "false"] },		// kvSecret reads: also return vault.json

		// Iterator mode
		iteratorPath:			{ param: "iteratorPath",				def: "" },		// kvSecret: folder to walk, empty = mount root
		iteratorRecursive:		{ param: "iteratorRecursive",			def: "true",	opt: ["true", "false"] },		// kvSecret: false = only the iteratorPath folder itself
		readData:				{ param: "readData",					def: "true",	opt: ["true", "false"] },		// true = each entry as Lookup returns it,
													// false = names only (vault.path etc.), one call per folder

		// Authentication
		authMethod:				{ param: "authMethod",					def: "approle",		opt: ["approle", "cert", "token"] },	// approle | cert | token
		authMount:				{ param: "authMount",					def: "" },		// empty = same as authMethod
		roleId:					{ param: "roleId",						def: "deb9023e-1480-f8ef-8acc-8a1064f1ad5d" },		// approle
		secretId:				{ param: "secretId",					def: "03efd7b8-0892-190b-4983-6f81c9b31ff8" },		// approle: secret_id, or wrapping token
		secretIdWrapped:		{ param: "secretIdWrapped",				def: "false",	opt: ["true", "false"] },		// approle: true = secretId is a wrapping token
		certRole:				{ param: "certRole",					def: "" },		// cert: role name, empty = any matching role
		token:					{ param: "vaultToken",					def: "" },		// token: for testing only

		// TLS: truststore for any auth method, keystore for cert auth
		tlsTruststore:			{ param: "tlsTruststore",				def: "" },		// empty = JVM default truststore
		tlsTruststorePassword:	{ param: "tlsTruststorePassword",		def: "" },
		tlsKeystore:			{ param: "tlsKeystore",					def: "" },		// client certificate + private key
		tlsKeystorePassword:	{ param: "tlsKeystorePassword",			def: "" },
		tlsStoreType:			{ param: "tlsStoreType",				def: "PKCS12",	opt: ["PKCS12", "JKS"] },	// PKCS12 | JKS
		tlsProtocol:			{ param: "tlsProtocol",					def: "TLSv1.2",		opt: ["TLSv1.2", "TLSv1.3"] },

		// Startup checks
		healthCheck:			{ param: "healthCheck",					def: "true",	opt: ["true", "false"] },		// sys/health before login
		capabilityCheckPath:	{ param: "capabilityCheckPath",			def: "" },		// sample path or name for the objectType, e.g. apps/tdi/db
		requiredCapabilities:	{ param: "requiredCapabilities",		def: "read",	opt: ["create", "read", "update", "patch", "delete", "list", "sudo"],	multi: true }	// e.g. read,create,update
	},

	objectTypes: {
		kvSecret:	"available - KV v2 secrets",
		policy:		"available - ACL policies",
		entity:		"available - identity entities, with aliases",
		group:		"available - identity groups, internal and external",
		dbCreds:	"planned, phase 4 - database secrets engine credentials"
	},

	modes: {
		kvSecret: {
			Lookup:		"read the secret. Link Criteria: vault.path equals $<attribute>, optionally vault.mount equals <mount>",
			AddOnly:	"write a new secret. Map vault.path (and optionally vault.mount) in the Output Map",
			Update:		"no match: write. Match: patch or replace, per updateMethod. Same mount as the lookup unless vault.mount is mapped",
			Delete:		"soft delete, or metadataDelete when deleteMode = permanent",
			Iterator:	"every secret in the iteratorPath folder, and below it when iteratorRecursive = true. Depth first: a folder's secrets, then its subfolders. Secrets whose latest version is deleted are skipped (with readData = false they are listed: without a read the connector cannot tell). Copying to another mount: do not map vault.mount, or map the new one",
			CallReply:	"any command below, selected by vault.command"
		},
		policy: {
			Lookup:		"read the policy. Link Criteria: vault.path equals <policy name>",
			AddOnly:	"create the policy from vault.path and vault.policy. Fails if it already exists",
			Update:		"no match: create. Match: replace the policy text",
			Delete:		"delete the policy, permanently. Vault refuses to delete default and root",
			Iterator:	"every ACL policy, root excepted (built in, cannot be read or written)",
			CallReply:	"any command below, selected by vault.command (list lists policies)"
		},
		entity: {
			Lookup:		"read the entity by name. Link Criteria: vault.path equals <entity name>",
			AddOnly:	"create the entity. Fails if it already exists",
			Update:		"no match: create. Match: metadata merged (patch) or set exactly (replace). vault.* fields change only when mapped",
			Delete:		"delete the entity and its aliases, permanently",
			Iterator:	"every entity. Includes the ones Vault creates by itself at login (entity_<id>)",
			CallReply:	"any command below, selected by vault.command (list lists entity names)"
		},
		group: {
			Lookup:		"read the group by name. Link Criteria: vault.path equals <group name>",
			AddOnly:	"create the group (vault.type: internal or external). Fails if it already exists",
			Update:		"no match: create. Match: metadata merged (patch) or set exactly (replace). vault.* fields change only when mapped",
			Delete:		"delete the group and its alias, permanently. Members are not affected",
			Iterator:	"every group, internal and external",
			CallReply:	"any command below, selected by vault.command (list lists group names)"
		}
	},

	// --- Attributes per objectType -------------------------------------------
	// Attributes not starting with vault. are the secret keys (kvSecret) or the
	// metadata (entity, group). Metadata values are strings: multi-valued
	// attributes are stored as JSON array text and read back as multi-valued.
	// Update mode: patch merges them with what is stored, replace keeps exactly
	// the mapped ones. The vault.* fields of an entity or group change only when
	// they are in the entry, with either updateMethod. An empty attribute clears
	// the field (e.g. no policies, no members, no aliases).
	// Iterator mode returns the same entry as Lookup (readData = true), or only
	// the name attributes (readData = false).
	attributes: {
		kvSecret: {
			"vault.path":		"string - secret path under the mount",
			"vault.mount":		"string - on writes optional, overrides kvMount. Returned by reads",
			"vault.name":		"string, read only - last part of vault.path",
			"vault.folder":		"string, read only - vault.path without its last part, empty at the mount root",
			"vault.relativePath":	"string, Iterator only - vault.path below iteratorPath",
			"vault.json":		"string - the whole secret as a JSON object. Read when kvJson = true. On writes, replaces the plain attributes",
			"vault.cas":		"int, optional, write only - see CAS",
			"vault.version":	"int, read only",
			"vault.created_time":	"string, RFC 3339, read only"
		},
		policy: {
			"vault.path":		"string - policy name. Vault stores names in lowercase",
			"vault.policy":		"string - the policy document, HCL or JSON"
		},
		entity: {
			"vault.path":		"string - entity name",
			"vault.id":		"string, read only",
			"vault.policies":	"multi-valued - policy names on the entity itself",
			"vault.disabled":	"true | false - true = the entity's tokens are refused",
			"vault.aliases":	"multi-valued - <auth mount>:<login name>, e.g. ldap:jdoe. The complete set: aliases not listed are removed",
			"vault.creation_time":	"string, RFC 3339, read only",
			"vault.last_update_time":	"string, RFC 3339, read only"
		},
		group: {
			"vault.path":		"string - group name",
			"vault.id":		"string, read only",
			"vault.type":		"internal | external - set at creation, cannot be changed. Default internal",
			"vault.policies":	"multi-valued - policy names, apply to all members",
			"vault.members":	"multi-valued - entity names. Internal groups only",
			"vault.memberGroups":	"multi-valued - names of member (sub)groups",
			"vault.alias":		"string - <auth mount>:<group name in the auth method>, e.g. ldap:vault-admins. External groups only",
			"vault.creation_time":	"string, RFC 3339, read only",
			"vault.last_update_time":	"string, RFC 3339, read only"
		}
	},

	// --- CallReply commands, selected by vault.command -----------------------
	// Every reply contains vault.status (the HTTP status code).
	// KV commands accept vault.mount to override the kvMount parameter.
	commands: {
		read: {
			http: "GET /v1/{mount}/data/{path}[?version=n]",
			query: {
				"vault.path":		"string, required - e.g. apps/tdi/db",
				"vault.version":	"int, optional - omit for the latest version"
			},
			response: {
				"<key>":		"one attribute per key in the secret",
				"vault.path":		"string",
				"vault.mount":		"string",
				"vault.name":		"string",
				"vault.folder":		"string",
				"vault.json":		"string - only when kvJson = true",
				"vault.version":	"int",
				"vault.created_time":	"string, RFC 3339",
				"vault.status":		"200 | 404 no such secret, or latest version deleted"
			}
		},
		write: {
			http: "POST /v1/{mount}/data/{path}",
			note: "New version holding exactly these keys. Keys not sent are dropped.",
			query: {
				"vault.path":		"string, required",
				"vault.cas":		"int, optional - 0 = create only, n = only if current version is n",
				"vault.json":		"string, optional - the secret as a JSON object, instead of the plain attributes",
				"<key>":		"every attribute not starting with vault. becomes a key"
			},
			response: {
				"vault.version":	"int - the new version",
				"vault.created_time":	"string, RFC 3339",
				"vault.status":		"200"
			}
		},
		patch: {
			http: "GET + POST /v1/{mount}/data/{path} with CAS (like vault kv patch -method=rw)",
			note: "Keys sent are added or changed, all other keys are kept. The secret must exist. Needs read + update capability.",
			query: {
				"vault.path":		"string, required",
				"vault.json":		"string, optional - keys to add or change as a JSON object, instead of the plain attributes",
				"<key>":		"keys to add or change"
			},
			response: {
				"vault.version":	"int - the new version",
				"vault.created_time":	"string, RFC 3339",
				"vault.status":		"200"
			}
		},
		list: {
			http: "LIST (sent as GET ?list=true) on /v1/{mount}/metadata/{path}, sys/policies/acl, identity/entity/name or identity/group/name",
			query: {
				"vault.objectType":	"string, optional - default: the objectType parameter",
				"vault.path":		"string, optional - kvSecret: folder, empty = mount root"
			},
			response: {
				"vault.keys":		"multi-valued - kvSecret: secret names, folders end with /. Others: names",
				"vault.status":		"200 | 404 nothing to list (empty or unknown folder)"
			}
		},
		"delete": {
			http: "DELETE /v1/{mount}/data/{path}",
			note: "Soft delete of the latest version. Recoverable with undelete.",
			query:		{ "vault.path": "string, required" },
			response:	{ "vault.status": "204" }
		},
		metadataRead: {
			http: "GET /v1/{mount}/metadata/{path}",
			query: { "vault.path": "string, required" },
			response: {
				"vault.current_version":	"int",
				"vault.oldest_version":		"int",
				"vault.max_versions":		"int, 0 = engine default",
				"vault.cas_required":		"true | false",
				"vault.created_time":		"string, RFC 3339",
				"vault.updated_time":		"string, RFC 3339",
				"vault.status":			"200 | 404"
			}
		},
		metadataDelete: {
			http: "DELETE /v1/{mount}/metadata/{path}",
			note: "Permanent: removes the secret and all its versions.",
			query:		{ "vault.path": "string, required" },
			response:	{ "vault.status": "204" }
		},
		health: {
			http: "GET /v1/sys/health (no token needed)",
			query: {},
			response: {
				"vault.initialized":	"true | false",
				"vault.sealed":		"true | false",
				"vault.standby":	"true | false",
				"vault.server_version":	"string, e.g. 1.17.2",
				"vault.cluster_name":	"string",
				"vault.status":		"200 ok | 503 sealed | 501 not initialized | 472 DR secondary"
			}
		},
		capabilities: {
			http: "POST /v1/sys/capabilities-self",
			query: {
				"vault.path":		"string - a KV secret path, checked as {mount}/data/{path}",
				"vault.apiPath":	"string - or any API path without /v1/, e.g. sys/mounts"
			},
			response: {
				"vault.apiPath":	"string - the path that was checked",
				"vault.capabilities":	"multi-valued - e.g. read, update. deny = no access",
				"vault.status":		"200"
			}
		},
		lookupSelf: {
			http: "GET /v1/auth/token/lookup-self",
			query: {},
			response: {
				"vault.display_name":	"string",
				"vault.policies":	"multi-valued",
				"vault.ttl":		"int seconds, 0 = never expires",
				"vault.expire_time":	"string, RFC 3339, or empty",
				"vault.status":		"200"
			}
		},
		unwrap: {
			http: "POST /v1/sys/wrapping/unwrap (the wrapping token is the credential)",
			note: "Single use: the wrapping token is invalid afterwards.",
			query: {
				"vault.wrappingToken":	"string, required"
			},
			response: {
				"<key>":		"one attribute per key in the wrapped data",
				"vault.status":		"200 | 400 token invalid, expired or already used"
			}
		}
	}
};

// =====================================================================
// State
// =====================================================================
var cfg = {};
var handler = null;		// objectType implementation for the standard modes
var sslFactory = null;		// set when a truststore or keystore is configured
var httpClient = null;		// ibmdi.HTTPClient instance when that transport is used
var clientToken = null;
var tokenRenewable = false;
var tokenExpiresAt = 0;		// epoch ms, 0 = no expiry
var tokenPolicies = "";
var approleSecretId = null;	// kept in memory after unwrapping, for re-login
var vault_authMounts = null;	// auth mount path ("ldap/") -> accessor, read from sys/auth once
var vault_idNames = {};		// "entity:<id>" / "group:<id>" -> name, for member lists
var vault_iter = null;		// Iterator state, set by selectEntries()
var vault_VERSION = "0.4.2";	// logged at startup. Keep in step with the header

// JSON: request bodies are native JavaScript objects and arrays, serialized with
// toJson(). Responses are parsed with fromJson() into native objects and arrays.

var STATUS_EOF = 0;		// result status: no entry found, or no more entries
var MAX_CAS_RETRIES = 3;
var NO_AUTH_COMMANDS = { health: true, unwrap: true };
var HEALTH_STATES = {
	"429": "an unsealed standby node",
	"472": "a disaster recovery secondary",
	"473": "a performance standby node",
	"501": "not initialized",
	"503": "sealed"
};

// =====================================================================
// Script Connector functions (no arguments: use entry, search, result)
// =====================================================================
function initialize() {
	main.logmsg("HashiCorp Vault Connector v" + vault_VERSION + " starting");
	loadConfig();
	handler = handlerFor(cfg.objectType);

	sslFactory = buildSslFactory();
	chooseTransport();
	if (cfg.healthCheck == "true") {
		assertHealthy();
	}
	login();
	if (cfg.capabilityCheckPath != "") {
		assertCapabilities();
	}
	main.logmsg("Vault connector v" + vault_VERSION + " ready: " + cfg.vaultUrl + " objectType=" + cfg.objectType + " auth=" + cfg.authMethod + " transport=" + (httpClient != null ? "httpClient" : "urlConnection") + " policies=" + tokenPolicies);
}

function terminate() {
	// Revoke only tokens this connector created, never a token handed to it
	if (clientToken != null && cfg.authMethod != "token") {
		try {
			vaultRequest("POST", "/v1/auth/token/revoke-self", null, {});
		} catch (ex) {
			main.logmsg("Vault token revoke failed: " + ex);
		}
	}
	clientToken = null;
	approleSecretId = null;
	vault_iter = null;
	if (httpClient != null) {
		try {
			httpClient.terminate();
		} catch (ex) {
			// nothing useful to do during shutdown
		}
		httpClient = null;
	}
}

// Lookup mode, and the search step of Update and Delete modes
function findEntry() {
	ensureToken();
	if (!handler.find(pathFromSearch(), mountFromSearch(), entry)) {
		result.setStatus(STATUS_EOF);		// no match: On No Match hook
	}
}

// AddOnly mode, and Update mode when no match was found
function putEntry() {
	ensureToken();
	handler.add(entry);
}

// Update mode, match found
function modEntry() {
	ensureToken();
	handler.modify(targetPath(), targetMount(), entry);
}

// Delete mode
function deleteEntry() {
	ensureToken();
	handler.remove(targetPath(), targetMount(), entry);
}

// Iterator mode: start a new pass
function selectEntries() {
	ensureToken();
	vault_iter = iterStart();
}

// Iterator mode: fill entry with the next object, or set end of data
function getNextEntry() {
	var it = vault_iter;
	if (it == null) {
		throw new java.lang.Exception("getNextEntry called before selectEntries");
	}
	ensureToken();
	while (!it.done) {
		var name = iterNextName(it);
		if (name == null) {
			it.done = true;
			main.logmsg("Vault Iterator done: " + it.returned + " entries, " + it.skipped + " skipped (deleted, or built in)");
			break;
		}
		var found = system.newEntry();
		if (iterRead(it, name, found)) {
			copyEntry(found, entry);
			it.returned++;
			return;
		}
		it.skipped++;
	}
	result.setStatus(STATUS_EOF);		// end of data
}

// CallReply mode: vault.command selects the operation, reply attributes are added to entry
function queryReply() {
	execute(req(entry, "vault.command"), entry, entry);
}

// =====================================================================
// objectType implementations for the standard modes
// =====================================================================
// Each implements:
//	find(path, mount, out)		Lookup, and the Iterator with readData. Fills out,
//					returns false for no match
//	add(entry)			AddOnly, and Update with no match
//	modify(path, mount, entry)	Update with a match
//	remove(path, mount, entry)	Delete
//	list(path, mount, out)		CallReply list, and the Iterator
//	apiPath(path, mount)		API path for the startup capability check
// For policy, entity and group, path is the object's name and mount is not used.
var objectTypes = {

	kvSecret: {
		find: function (path, mount, out) {
			return kvRead(path, null, mount, out) == 200;
		},
		add: function (e) {
			kvWrite(req(e, "vault.path"), kvData(e), opt(e, "vault.cas"), mountOf(e), system.newEntry());
		},
		modify: function (path, mount, e) {
			if (cfg.updateMethod == "replace") {
				kvWrite(path, kvData(e), opt(e, "vault.cas"), mount, system.newEntry());
			} else {
				kvPatch(path, kvData(e), mount, system.newEntry());
			}
		},
		remove: function (path, mount, e) {
			kvDelete(path, cfg.deleteMode == "permanent", mount, system.newEntry());
		},
		list: function (path, mount, out) {
			kvList(path, mount, out);
		},
		apiPath: function (path, mount) {
			return cleanPath(mount) + "/data/" + cleanPath(path);
		}
	},

	policy: {
		find: function (name, mount, out) {
			var d = readNamed(policyApi(name), "policy read " + name, name, out);
			if (d == null) {
				return false;
			}
			out.setAttribute("vault.policy", String(d.policy));
			return true;
		},
		add: function (e) {
			var name = req(e, "vault.path");
			assertAbsent(policyApi(name), "Policy", name);
			policyWrite(name, req(e, "vault.policy"));
		},
		modify: function (name, mount, e) {
			policyWrite(name, req(e, "vault.policy"));
		},
		remove: function (name, mount, e) {
			deleteObject(policyApi(name), "policy delete " + name);
		},
		list: function (path, mount, out) {
			listNames("sys/policies/acl", out);
		},
		apiPath: function (name, mount) {
			return "sys/policies/acl/" + cleanPath(name);
		}
	},

	entity: {
		find: function (name, mount, out) {
			var d = readNamed(entityApi(name), "entity read " + name, name, out);
			if (d == null) {
				return false;
			}
			entityToEntry(d, out);
			return true;
		},
		add: function (e) {
			var name = req(e, "vault.path");
			assertAbsent(entityApi(name), "Entity", name);
			entityWrite(name, e, null);
		},
		modify: function (name, mount, e) {
			entityWrite(name, e, existing(entityApi(name), "Entity", name));
		},
		remove: function (name, mount, e) {
			deleteObject(entityApi(name), "entity delete " + name);
		},
		list: function (path, mount, out) {
			listNames("identity/entity/name", out);
		},
		apiPath: function (name, mount) {
			return "identity/entity/name/" + cleanPath(name);
		}
	},

	group: {
		find: function (name, mount, out) {
			var d = readNamed(groupApi(name), "group read " + name, name, out);
			if (d == null) {
				return false;
			}
			groupToEntry(d, out);
			return true;
		},
		add: function (e) {
			var name = req(e, "vault.path");
			assertAbsent(groupApi(name), "Group", name);
			groupWrite(name, e, null);
		},
		modify: function (name, mount, e) {
			groupWrite(name, e, existing(groupApi(name), "Group", name));
		},
		remove: function (name, mount, e) {
			deleteObject(groupApi(name), "group delete " + name);
		},
		list: function (path, mount, out) {
			listNames("identity/group/name", out);
		},
		apiPath: function (name, mount) {
			return "identity/group/name/" + cleanPath(name);
		}
	}

	// dbCreds: phase 4.
};

function handlerFor(type) {
	var h = objectTypes[type];
	if (h == null) {
		if (vault_params.objectTypes[type] != null) {
			notYet("objectType '" + type + "'", vault_params.objectTypes[type]);
		}
		throw new java.lang.Exception("Unknown objectType '" + type + "'. Valid: " + keysOf(vault_params.objectTypes).join(", "));
	}
	return h;
}

// =====================================================================
// Iterator mode
// =====================================================================
// One entry per object. kvSecret is walked lazily, one folder at a time and
// depth first (a folder's secrets, then its subfolders in order), so only the
// folders still to visit and the current folder's names are held in memory.
// policy, entity and group are flat: one LIST, then one read per name.
// Vault's LIST has no paging: each folder, or the whole name list, comes in
// one response.
function iterStart() {
	var it = {
		mount:		cleanPath(cfg.kvMount),
		base:		cleanPath(cfg.iteratorPath),
		folders:	[],		// kvSecret: folders still to list, the last one is next
		names:		[],		// paths or names from the current listing
		pos:		0,		// next index in names
		returned:	0,
		skipped:	0,
		done:		false
	};
	if (cfg.objectType == "kvSecret") {
		it.folders.push(it.base);
	} else {
		var list = system.newEntry();
		handler.list("", it.mount, list);
		it.names = values(list, "vault.keys");
	}
	return it;
}

// Next path or name, listing folders as needed. null = no more.
function iterNextName(it) {
	while (it.pos >= it.names.length && it.folders.length > 0) {
		iterListFolder(it, it.folders.pop());
	}
	if (it.pos >= it.names.length) {
		return null;
	}
	return it.names[it.pos++];
}

// kvSecret: the folder's secrets become the next names, its subfolders are
// queued. A key can be both a secret and a folder (db and db/): both are kept.
function iterListFolder(it, folder) {
	var list = system.newEntry();
	kvList(folder, it.mount, list);		// 404 = empty or unknown folder: nothing to add
	var keys = values(list, "vault.keys");
	var secrets = [];
	var subfolders = [];
	for (var i = 0; i < keys.length; i++) {
		var p = (folder == "") ? keys[i] : folder + "/" + keys[i];
		if (/\/$/.test(keys[i])) {
			if (cfg.iteratorRecursive == "true") {
				subfolders.push(cleanPath(p));
			}
		} else {
			secrets.push(p);
		}
	}
	// Pushed in reverse, so the first subfolder is listed next
	for (var j = subfolders.length - 1; j >= 0; j--) {
		it.folders.push(subfolders[j]);
	}
	it.names = secrets;
	it.pos = 0;
}

// Fills out for one path or name. false = skip it.
function iterRead(it, name, out) {
	if (cfg.objectType == "kvSecret") {
		if (cfg.readData == "true") {
			if (kvRead(name, null, it.mount, out) != 200) {
				return false;		// latest version deleted or destroyed, or gone since the listing
			}
		} else {
			setPathAttrs(out, name, it.mount);
		}
		out.setAttribute("vault.relativePath", relativeTo(name, it.base));
		return true;
	}
	if (cfg.objectType == "policy" && name == "root") {
		return false;		// built in: cannot be read or written
	}
	if (cfg.readData == "true") {
		return handler.find(name, it.mount, out);		// false = deleted since the listing
	}
	out.setAttribute("vault.path", name);
	return true;
}

// =====================================================================
// CallReply commands: fn(input entry, output entry)
// =====================================================================
var commands = {

	read: function (e, out) {
		kvRead(req(e, "vault.path"), opt(e, "vault.version"), mountOf(e), out);
	},

	write: function (e, out) {
		kvWrite(req(e, "vault.path"), kvData(e), opt(e, "vault.cas"), mountOf(e), out);
	},

	patch: function (e, out) {
		kvPatch(req(e, "vault.path"), kvData(e), mountOf(e), out);
	},

	// Lists objects of the objectType parameter, or of vault.objectType if given
	list: function (e, out) {
		handlerFor(opt(e, "vault.objectType") || cfg.objectType).list(opt(e, "vault.path") || "", mountOf(e), out);
	},

	"delete": function (e, out) {
		kvDelete(req(e, "vault.path"), false, mountOf(e), out);
	},

	metadataRead: function (e, out) {
		kvMetadataRead(req(e, "vault.path"), mountOf(e), out);
	},

	metadataDelete: function (e, out) {
		kvDelete(req(e, "vault.path"), true, mountOf(e), out);
	},

	health: function (e, out) {
		sysHealth(out);
	},

	capabilities: function (e, out) {
		var api = opt(e, "vault.apiPath");
		if (api == null) {
			api = cleanPath(mountOf(e)) + "/data/" + cleanPath(req(e, "vault.path"));
		}
		var caps = capabilitiesSelf(api);
		out.setAttribute("vault.status", 200);
		out.setAttribute("vault.apiPath", api);
		for (var i = 0; i < caps.length; i++) {
			out.addAttributeValue("vault.capabilities", caps[i]);
		}
	},

	lookupSelf: function (e, out) {
		var r = vaultCall("GET", "/v1/auth/token/lookup-self", null);
		checkStatus(r, "lookup-self");
		var d = r.json.data;
		out.setAttribute("vault.status", r.status);
		setMeta(out, d, ["display_name", "ttl"]);
		out.setAttribute("vault.expire_time", d.expire_time == null ? "" : String(d.expire_time));
		addValues(out, "vault.policies", d.policies);
	},

	unwrap: function (e, out) {
		var r = vaultRequest("POST", "/v1/sys/wrapping/unwrap", null, { token: req(e, "vault.wrappingToken") });
		out.setAttribute("vault.status", r.status);
		checkStatus(r, "unwrap");
		if (r.json != null && r.json.data != null) {
			dataToEntry(r.json.data, out);
		}
	}
};

function execute(cmd, input, out) {
	var name = String(cmd);
	var fn = commands[name];
	if (fn == null) {
		throw new java.lang.Exception("Unknown vault.command '" + name + "'. Valid: " + keysOf(commands).join(", "));
	}
	if (!NO_AUTH_COMMANDS[name]) {
		ensureToken();
	}
	fn(input, out);
}

// =====================================================================
// KV v2 secrets engine
// =====================================================================
function kvRead(path, version, mount, out) {
	var api = kvApi("data", path, mount);
	if (version != null) {
		api += "?version=" + parseInt(version, 10);
	}
	var r = vaultCall("GET", api, null);
	out.setAttribute("vault.status", r.status);
	setPathAttrs(out, path, mount);
	if (r.status == 404) {
		return 404;
	}
	checkStatus(r, "read " + path);
	var d = r.json.data;
	dataToEntry(d.data, out);
	setMeta(out, d.metadata, ["version", "created_time"]);
	if (cfg.kvJson == "true") {
		out.setAttribute("vault.json", String(toJson((d.data != null) ? d.data : {})));
	}
	return r.status;
}

function kvWrite(path, data, cas, mount, out) {
	var r = kvPost(path, data, cas, mount);
	checkStatus(r, "write " + path);
	applyWriteResult(r, path, out);
}

// Read, merge, write with check-and-set. Retries if another writer got in between.
// (Java's HttpURLConnection cannot send HTTP PATCH, so this is the -method=rw variant.)
function kvPatch(path, changes, mount, out) {
	for (var attempt = 1; attempt <= MAX_CAS_RETRIES; attempt++) {
		var cur = vaultCall("GET", kvApi("data", path, mount), null);
		if (cur.status == 404) {
			throw new java.lang.Exception("Vault patch " + path + ": secret does not exist (or latest version is deleted)");
		}
		checkStatus(cur, "patch (read) " + path);
		var d = cur.json.data;
		var merged = {};
		copyProps(d.data, merged);
		copyProps(changes, merged);

		var w = kvPost(path, merged, d.metadata.version, mount);
		if (w.status == 400 && w.text.indexOf("check-and-set") >= 0) {
			continue;		// someone else wrote a new version: re-read and merge again
		}
		checkStatus(w, "patch (write) " + path);
		applyWriteResult(w, path, out);
		return;
	}
	throw new java.lang.Exception("Vault patch " + path + ": gave up after " + MAX_CAS_RETRIES + " check-and-set conflicts");
}

function kvPost(path, data, cas, mount) {
	var body = {};
	body.data = data;
	if (cas != null) {
		body.options = {};
		body.options.cas = parseInt(String(cas), 10);
	}
	return vaultCall("POST", kvApi("data", path, mount), body);
}

function applyWriteResult(r, path, out) {
	out.setAttribute("vault.status", r.status);
	out.setAttribute("vault.path", path);
	if (r.json != null) {
		setMeta(out, r.json.data, ["version", "created_time"]);
	}
}

function kvList(path, mount, out) {
	var r = vaultCall("GET", kvApi("metadata", path, mount) + "?list=true", null);
	out.setAttribute("vault.status", r.status);
	if (r.status == 404) {
		return;
	}
	checkStatus(r, "list " + path);
	addValues(out, "vault.keys", r.json.data.keys);
}

// permanent = false: soft delete of the latest version. true: metadata delete, all versions gone.
function kvDelete(path, permanent, mount, out) {
	var r = vaultCall("DELETE", kvApi(permanent ? "metadata" : "data", path, mount), null);
	checkStatus(r, (permanent ? "metadataDelete " : "delete ") + path);
	out.setAttribute("vault.status", r.status);
}

function kvMetadataRead(path, mount, out) {
	var r = vaultCall("GET", kvApi("metadata", path, mount), null);
	out.setAttribute("vault.status", r.status);
	out.setAttribute("vault.path", path);
	if (r.status == 404) {
		return;
	}
	checkStatus(r, "metadataRead " + path);
	setMeta(out, r.json.data, ["current_version", "oldest_version", "max_versions", "cas_required", "created_time", "updated_time"]);
}

// Secret data to write: vault.json when it is in the entry, stored as it is
// (nested objects, numbers and booleans survive), else the plain attributes
function kvData(e) {
	var text = opt(e, "vault.json");
	if (text == null) {
		return entryToData(e);
	}
	var d = parseJson(text);
	if (d == null || typeof d != "object" || d instanceof Array) {
		throw new java.lang.Exception("vault.json must hold a JSON object, e.g. {\"username\": \"svc_tdi\"}");
	}
	return d;
}

// vault.path, vault.mount, vault.name and vault.folder of a secret
function setPathAttrs(out, path, mount) {
	var p = cleanPath(path);
	var i = p.lastIndexOf("/");
	out.setAttribute("vault.path", p);
	out.setAttribute("vault.mount", cleanPath(mount));
	out.setAttribute("vault.name", (i < 0) ? p : p.substring(i + 1));
	out.setAttribute("vault.folder", (i < 0) ? "" : p.substring(0, i));
}

// =====================================================================
// ACL policies
// =====================================================================
function policyApi(name) {
	return "/v1/sys/policies/acl/" + encodeName(name);
}

function policyWrite(name, text) {
	var body = {};
	body.policy = text;
	checkStatus(vaultCall("POST", policyApi(name), body), "policy write " + name);
}

// =====================================================================
// Identity: entities and aliases
// =====================================================================
function entityApi(name) {
	return "/v1/identity/entity/name/" + encodeName(name);
}

// cur: the entity as read from Vault, or null to create it
function entityWrite(name, e, cur) {
	// Check the aliases before writing anything, so a bad one changes nothing
	var aliases = isMapped(e, "vault.aliases") ? parseEntityAliases(values(e, "vault.aliases")) : null;

	var body = {};
	body.metadata = metadataFor(e, cur);
	if (isMapped(e, "vault.policies")) {
		body.policies = values(e, "vault.policies");
	}
	if (isMapped(e, "vault.disabled")) {
		body.disabled = String(opt(e, "vault.disabled")).toLowerCase() == "true";
	}
	var r = vaultCall("POST", entityApi(name), body);
	checkStatus(r, (cur == null ? "entity create " : "entity update ") + name);

	if (aliases != null) {
		var id = (cur != null) ? String(cur.id) : createdId(r, entityApi(name), "Entity", name);
		syncEntityAliases(id, aliases, (cur != null && cur.aliases != null) ? cur.aliases : []);
	}
}

// vault.aliases values -> parsed aliases. Vault allows one alias per auth mount per entity.
function parseEntityAliases(specs) {
	var list = [];
	var seen = {};
	for (var i = 0; i < specs.length; i++) {
		var a = parseAlias(specs[i]);
		if (seen[a.accessor]) {
			throw new java.lang.Exception("vault.aliases has more than one alias for auth mount '" + a.mount + "'. Vault allows one per mount per entity");
		}
		seen[a.accessor] = true;
		list.push(a);
	}
	return list;
}

// The parsed aliases are the complete set: missing aliases are created, renamed
// ones updated, and aliases not listed are removed. Matched by auth mount.
function syncEntityAliases(entityId, wanted, current) {
	var keep = {};
	for (var i = 0; i < wanted.length; i++) {
		var a = wanted[i];
		keep[a.accessor] = true;

		var found = null;
		for (var j = 0; j < current.length; j++) {
			if (String(current[j].mount_accessor) == a.accessor) {
				found = current[j];
			}
		}
		if (found != null && String(found.name) == a.name) {
			continue;		// already there
		}
		var body = {};
		body.name = a.name;
		body.canonical_id = entityId;
		body.mount_accessor = a.accessor;
		var api = (found != null) ? "/v1/identity/entity-alias/id/" + encodeName(found.id) : "/v1/identity/entity-alias";
		checkStatus(vaultCall("POST", api, body), "entity alias " + a.mount + ":" + a.name);
	}
	for (var k = 0; k < current.length; k++) {
		if (!keep[String(current[k].mount_accessor)]) {
			deleteObject("/v1/identity/entity-alias/id/" + encodeName(current[k].id), "entity alias delete " + aliasText(current[k]));
		}
	}
}

function entityToEntry(d, out) {
	metadataToEntry(d.metadata, out);
	setMeta(out, d, ["id", "disabled", "creation_time", "last_update_time"]);
	addValues(out, "vault.policies", d.policies);
	for (var i = 0; d.aliases != null && i < d.aliases.length; i++) {
		out.addAttributeValue("vault.aliases", aliasText(d.aliases[i]));
	}
}

// =====================================================================
// Identity: groups and group aliases
// =====================================================================
function groupApi(name) {
	return "/v1/identity/group/name/" + encodeName(name);
}

// cur: the group as read from Vault, or null to create it
function groupWrite(name, e, cur) {
	var type = String(opt(e, "vault.type") || (cur != null ? cur.type : "internal")).toLowerCase();
	if (type != "internal" && type != "external") {
		throw new java.lang.Exception("vault.type must be internal or external, not '" + type + "'");
	}
	if (cur != null && type != String(cur.type)) {
		throw new java.lang.Exception("Group '" + name + "' is " + cur.type + ". Vault cannot change a group's type: delete it and create it again");
	}
	if (type == "external" && isMapped(e, "vault.members")) {
		throw new java.lang.Exception("Group '" + name + "' is external: Vault fills its members from the auth method through vault.alias, so vault.members cannot be set");
	}
	if (type == "internal" && opt(e, "vault.alias") != null) {
		throw new java.lang.Exception("Group '" + name + "' is internal: only external groups have a vault.alias");
	}

	// Check the alias before writing anything, so a bad one changes nothing
	var aliasMapped = (type == "external" && isMapped(e, "vault.alias"));
	var alias = (aliasMapped && opt(e, "vault.alias") != null) ? parseAlias(opt(e, "vault.alias")) : null;

	var body = {};
	if (cur == null) {
		body.type = type;
	}
	body.metadata = metadataFor(e, cur);
	if (isMapped(e, "vault.policies")) {
		body.policies = values(e, "vault.policies");
	}
	if (isMapped(e, "vault.members")) {
		body.member_entity_ids = idsOf("entity", values(e, "vault.members"), "vault.members");
	}
	if (isMapped(e, "vault.memberGroups")) {
		body.member_group_ids = idsOf("group", values(e, "vault.memberGroups"), "vault.memberGroups");
	}
	var r = vaultCall("POST", groupApi(name), body);
	checkStatus(r, (cur == null ? "group create " : "group update ") + name);

	if (aliasMapped) {
		var id = (cur != null) ? String(cur.id) : createdId(r, groupApi(name), "Group", name);
		syncGroupAlias(id, alias, (cur != null) ? cur.alias : null);
	}
}

// An external group has one alias: the group's name in the auth method.
// a: the parsed alias, or null (empty vault.alias) to remove it.
function syncGroupAlias(groupId, a, cur) {
	var hasCur = (cur != null && cur.id != null && String(cur.id) != "");
	if (a == null) {
		if (hasCur) {
			deleteObject("/v1/identity/group-alias/id/" + encodeName(cur.id), "group alias delete " + aliasText(cur));
		}
		return;
	}
	if (hasCur && String(cur.mount_accessor) == a.accessor && String(cur.name) == a.name) {
		return;			// already there
	}
	var body = {};
	body.name = a.name;
	body.mount_accessor = a.accessor;
	body.canonical_id = groupId;
	var api = hasCur ? "/v1/identity/group-alias/id/" + encodeName(cur.id) : "/v1/identity/group-alias";
	checkStatus(vaultCall("POST", api, body), "group alias " + a.mount + ":" + a.name);
}

function groupToEntry(d, out) {
	metadataToEntry(d.metadata, out);
	setMeta(out, d, ["id", "type", "creation_time", "last_update_time"]);
	addValues(out, "vault.policies", d.policies);
	addValues(out, "vault.members", namesOf("entity", d.member_entity_ids));
	addValues(out, "vault.memberGroups", namesOf("group", d.member_group_ids));
	if (d.alias != null && d.alias.name != null && String(d.alias.name) != "") {
		out.setAttribute("vault.alias", aliasText(d.alias));
	}
}

// Vault stores memberships by ID. Entity or group names -> IDs.
function idsOf(kind, names, attr) {
	var ids = [];
	for (var i = 0; i < names.length; i++) {
		var d = fetchObject("/v1/identity/" + kind + "/name/" + encodeName(names[i]), kind + " read " + names[i]);
		if (d == null) {
			throw new java.lang.Exception(attr + ": there is no " + kind + " named '" + names[i] + "'");
		}
		vault_idNames[kind + ":" + d.id] = names[i];
		ids.push(String(d.id));
	}
	return ids;
}

// IDs -> names, cached for the connector's lifetime. An ID that no longer
// exists is returned as is.
function namesOf(kind, ids) {
	var names = [];
	for (var i = 0; ids != null && i < ids.length; i++) {
		var key = kind + ":" + ids[i];
		if (vault_idNames[key] == null) {
			var d = fetchObject("/v1/identity/" + kind + "/id/" + encodeName(ids[i]), kind + " read " + ids[i]);
			vault_idNames[key] = (d == null) ? String(ids[i]) : String(d.name);
		}
		names.push(vault_idNames[key]);
	}
	return names;
}

// =====================================================================
// Shared by policy, entity and group
// =====================================================================
// GET a named object: its data, or null if it does not exist
function fetchObject(api, what) {
	var r = vaultCall("GET", api, null);
	if (r.status == 404) {
		return null;
	}
	checkStatus(r, what);
	return (r.json.data != null) ? r.json.data : r.json;
}

// fetchObject for Lookup: also sets vault.status and vault.path on out
function readNamed(api, what, name, out) {
	var d = fetchObject(api, what);
	out.setAttribute("vault.status", (d == null) ? 404 : 200);
	out.setAttribute("vault.path", name);
	return d;
}

function existing(api, kind, name) {
	var d = fetchObject(api, kind.toLowerCase() + " read " + name);
	if (d == null) {
		throw new java.lang.Exception(kind + " '" + name + "' does not exist");
	}
	return d;
}

// AddOnly never overwrites an existing policy, entity or group
function assertAbsent(api, kind, name) {
	if (fetchObject(api, kind.toLowerCase() + " read " + name) != null) {
		throw new java.lang.Exception(kind + " '" + name + "' already exists. AddOnly does not overwrite: use Update mode to change it");
	}
}

function deleteObject(api, what) {
	checkStatus(vaultCall("DELETE", api, null), what);
}

// ID of an object just created: from the response, or read back by name
function createdId(r, api, kind, name) {
	if (r.json != null && r.json.data != null && r.json.data.id != null) {
		return String(r.json.data.id);
	}
	return String(existing(api, kind, name).id);
}

function listNames(base, out) {
	var r = vaultCall("GET", "/v1/" + base + "?list=true", null);
	out.setAttribute("vault.status", r.status);
	if (r.status == 404) {
		return;
	}
	checkStatus(r, "list " + base);
	addValues(out, "vault.keys", r.json.data.keys);
}

// Plain attributes -> Vault metadata, which holds string values only.
// Multi-valued attributes are stored as JSON array text.
// patch merges with the stored metadata. replace, and create, use exactly the entry's.
function metadataFor(e, cur) {
	var meta = {};
	if (cur != null && cfg.updateMethod != "replace") {
		copyProps(cur.metadata, meta);
	}
	var data = entryToData(e);
	for (var k in data) {
		meta[k] = (data[k] instanceof Array) ? String(toJson(data[k])) : data[k];
	}
	return meta;
}

// Vault metadata -> attributes. JSON array text becomes multi-valued again.
function metadataToEntry(map, out) {
	if (map == null) {
		return;
	}
	for (var k in map) {
		var v = (map[k] == null) ? "" : String(map[k]);
		var arr = (v.charAt(0) == "[") ? parseJson(v) : null;
		if (arr instanceof Array) {
			addValues(out, k, arr);
		} else {
			out.setAttribute(k, v);
		}
	}
}

// "<auth mount>:<name>", e.g. ldap:jdoe. The mount can also be given by its
// accessor (auth_ldap_1a2b3c4d), which needs no read access to sys/auth.
function parseAlias(spec) {
	var s = String(spec);
	var i = s.indexOf(":");
	if (i <= 0 || i == s.length - 1) {
		throw new java.lang.Exception("Alias '" + s + "' must be <auth mount>:<name>, e.g. ldap:jdoe");
	}
	var mount = cleanPath(s.substring(0, i));
	return { mount: mount, name: s.substring(i + 1), accessor: accessorOf(mount) };
}

function accessorOf(mount) {
	if (/^auth_/.test(mount)) {
		return mount;
	}
	if (vault_authMounts == null) {
		var r = vaultCall("GET", "/v1/sys/auth", null);
		if (r.status == 403) {
			throw new java.lang.Exception("Reading sys/auth was denied. Give the connector's policy read on sys/auth, or write the alias with the mount accessor (auth_ldap_...) instead of the mount path");
		}
		checkStatus(r, "sys/auth");
		var src = (r.json.data != null) ? r.json.data : r.json;
		var map = {};
		for (var k in src) {
			if (src[k] != null && typeof src[k] == "object" && src[k].accessor != null) {
				map[String(k)] = String(src[k].accessor);
			}
		}
		vault_authMounts = map;
	}
	var acc = vault_authMounts[mount + "/"];
	if (acc == null) {
		throw new java.lang.Exception("No auth method is enabled at '" + mount + "'. Enabled: " + keysOf(vault_authMounts).join(", "));
	}
	return acc;
}

// Alias as read from Vault -> "<auth mount>:<name>"
function aliasText(a) {
	var mount = (a.mount_path != null && String(a.mount_path) != "")
		? cleanPath(String(a.mount_path).replace(/^\/?auth\//, ""))
		: String(a.mount_accessor);
	return mount + ":" + String(a.name);
}

// =====================================================================
// Health and capability checks
// =====================================================================
function sysHealth(out) {
	// standbyok / perfstandbyok: a healthy standby node also answers 200
	var r = vaultRequest("GET", "/v1/sys/health?standbyok=true&perfstandbyok=true", null, { noToken: true, rootNamespace: true });
	out.setAttribute("vault.status", r.status);
	if (r.json != null) {
		setMeta(out, r.json, ["initialized", "sealed", "standby", "cluster_name"]);
		if (r.json.version != null) {
			out.setAttribute("vault.server_version", String(r.json.version));
		}
	}
	return r.status;
}

function assertHealthy() {
	var out = system.newEntry();
	var status = sysHealth(out);
	if (status != 200) {
		var state = HEALTH_STATES[String(status)] || ("unhealthy (HTTP " + status + ")");
		throw new java.lang.Exception("Vault at " + cfg.vaultUrl + " is " + state);
	}
	main.logmsg("Vault health OK: version " + out.getString("vault.server_version") + ", cluster " + out.getString("vault.cluster_name"));
}

function capabilitiesSelf(apiPath) {
	var body = {};
	body.paths = [];
	body.paths.push(apiPath);
	var r = vaultCall("POST", "/v1/sys/capabilities-self", body);
	checkStatus(r, "capabilities-self");
	var list = r.json[apiPath];
	if (list == null) {
		list = r.json.capabilities;
	}
	if (list == null && r.json.data != null) {
		list = r.json.data[apiPath];
	}
	var caps = [];
	for (var i = 0; list != null && i < list.length; i++) {
		caps.push(String(list[i]));
	}
	return caps;
}

// Checks capabilityCheckPath as a path or name of the configured objectType
function assertCapabilities() {
	var api = handler.apiPath(cfg.capabilityCheckPath, cfg.kvMount);
	var caps = capabilitiesSelf(api);
	if (contains(caps, "root")) {
		return;
	}
	var needed = cfg.requiredCapabilities.split(",");
	var missing = [];
	for (var i = 0; i < needed.length; i++) {
		var c = trim(needed[i]);
		if (c != "" && !contains(caps, c)) {
			missing.push(c);
		}
	}
	if (missing.length > 0) {
		throw new java.lang.Exception("Vault token with policies " + tokenPolicies + " is missing [" + missing.join(", ") + "] on " + api + " (has: " + caps.join(", ") + "). Check the policy attached to the auth role.");
	}
}

// =====================================================================
// Authentication
// =====================================================================
function login() {
	var method = cfg.authMethod;
	var r;

	if (method == "token") {
		clientToken = cfg.token;
		r = vaultRequest("GET", "/v1/auth/token/lookup-self", null, {});
		checkStatus(r, "token lookup-self");
		var d = r.json.data;
		setToken(cfg.token, d.renewable, d.ttl, d.policies);
		return;
	}

	var body = {};
	if (method == "approle") {
		if (approleSecretId == null) {
			approleSecretId = (cfg.secretIdWrapped == "true") ? unwrapSecretId(cfg.secretId) : cfg.secretId;
		}
		body.role_id = cfg.roleId;
		body.secret_id = approleSecretId;
	} else if (method == "cert") {
		if (cfg.tlsKeystore == "") {
			throw new java.lang.Exception("authMethod=cert needs tlsKeystore (client certificate and key)");
		}
		if (cfg.certRole != "") {
			body.name = cfg.certRole;
		}
		// The credential is the client certificate, presented in the TLS handshake
	} else {
		throw new java.lang.Exception("Unknown authMethod '" + method + "'. Valid: approle, cert, token");
	}

	clientToken = null;
	r = vaultRequest("POST", "/v1/auth/" + cfg.authMount + "/login", body, { noToken: true });
	if (r.status == 400 && method == "approle" && cfg.secretIdWrapped == "true") {
		throw new java.lang.Exception("AppRole login failed: " + errorText(r) + ". If this is a re-login, the unwrapped secret_id may be single-use (set secret_id_num_uses=0 on the role, or restart with a new wrapping token).");
	}
	checkStatus(r, method + " login");
	var a = r.json.auth;
	setToken(String(a.client_token), a.renewable, a.lease_duration, a.policies);
}

// Response wrapping: verify where the wrapping token came from, then unwrap it (single use)
function unwrapSecretId(wrappingToken) {
	var lookupBody = {};
	lookupBody.token = wrappingToken;
	var lr = vaultRequest("POST", "/v1/sys/wrapping/lookup", lookupBody, { token: wrappingToken });
	if (lr.status >= 400) {
		throw new java.lang.Exception("Wrapping token is invalid, expired or already used: " + errorText(lr));
	}
	var creationPath = String(lr.json.data.creation_path);
	var expectedPrefix = "auth/" + cfg.authMount + "/role/";
	if (creationPath.indexOf(expectedPrefix) != 0 || !/\/secret-id$/.test(creationPath)) {
		throw new java.lang.Exception("Wrapping token was created by '" + creationPath + "', not by AppRole secret-id generation. Refusing to unwrap (possible tampering).");
	}
	var r = vaultRequest("POST", "/v1/sys/wrapping/unwrap", null, { token: wrappingToken });
	checkStatus(r, "unwrap secret_id");
	main.logmsg("AppRole secret_id unwrapped from " + creationPath);
	return String(r.json.data.secret_id);
}

// Renew shortly before expiry, fall back to a fresh login
function ensureToken() {
	if (tokenExpiresAt == 0 || now() < tokenExpiresAt - 60000) {
		return;
	}
	if (tokenRenewable) {
		var r = vaultRequest("POST", "/v1/auth/token/renew-self", null, {});
		if (r.status == 200) {
			setExpiry(r.json.auth.lease_duration);
			return;
		}
	}
	if (cfg.authMethod == "token") {
		throw new java.lang.Exception("Vault token expired and cannot be renewed. Supply a new vaultToken.");
	}
	login();
}

function setToken(token, renewable, ttl, policies) {
	clientToken = token;
	tokenRenewable = String(renewable) == "true";
	tokenPolicies = (policies == null) ? "" : ((policies instanceof Array) ? policies.join(", ") : String(policies));
	setExpiry(ttl);
}

function setExpiry(seconds) {
	var s = Number(seconds);
	tokenExpiresAt = (s > 0) ? now() + s * 1000 : 0;
}

// =====================================================================
// HTTP and TLS
// =====================================================================
// opts: token (override), noToken, retry (re-login once on 403), rootNamespace
function vaultRequest(method, apiPath, body, opts) {
	opts = opts || {};
	var token = opts.noToken ? null : (opts.token != null ? opts.token : clientToken);

	var headers = { "Accept": "application/json" };
	if (token != null && token != "") {
		headers["X-Vault-Token"] = token;
	}
	if (cfg.namespace != "" && !opts.rootNamespace) {
		headers["X-Vault-Namespace"] = cfg.namespace;
	}
	var bodyText = null;
	if (body != null) {
		headers["Content-Type"] = "application/json; charset=utf-8";
		bodyText = String(toJson(body));
	}

	var url = cfg.vaultUrl + apiPath;
	var res = (httpClient != null)
		? sendViaHttpClient(method, url, headers, bodyText)
		: sendViaUrlConnection(method, url, headers, bodyText);

	// 403 = token expired or revoked (or missing policy): log in again once and retry
	if (res.status == 403 && opts.retry && cfg.authMethod != "token") {
		login();
		opts.retry = false;
		return vaultRequest(method, apiPath, body, opts);
	}
	return { status: res.status, text: res.text, json: parseJson(res.text) };
}

// Transport 1: the standard HTTP Client Connector in CallReply style.
// Request entry: http.url, http.method, http.body, headers as http.<Header>.
// Response entry: http.responseCode (always set), http.bodyAsBytes.
function sendViaHttpClient(method, url, headers, bodyText) {
	var req = system.newEntry();
	req.setAttribute("http.url", url);
	req.setAttribute("http.method", method);
	for (var h in headers) {
		req.setAttribute("http." + h, headers[h]);
	}
	if (bodyText != null) {
		req.setAttribute("http.body", bodyText);
	}
	var res = httpClient.queryReply(req);
	var code = res.getString("http.responseCode");
	// Vault sends JSON without a charset, and bodyAsString then decodes it as
	// Latin-1. JSON is always UTF-8, so decode the raw bytes ourselves.
	var bytes = res.getObject("http.bodyAsBytes");
	var text = (bytes == null) ? "" : String(new java.lang.String(bytes, "UTF-8"));
	return {
		status: (code == null) ? 0 : parseInt(String(code), 10),
		text: text
	};
}

// Transport 2: plain HttpURLConnection, with this connector's own TLS context (cert auth)
function sendViaUrlConnection(method, url, headers, bodyText) {
	var con = new java.net.URL(url).openConnection();
	if (sslFactory != null && url.indexOf("https:") == 0) {
		con.setSSLSocketFactory(sslFactory);
	}
	con.setRequestMethod(method);
	var timeout = parseInt(cfg.timeoutMs, 10);
	con.setConnectTimeout(timeout);
	con.setReadTimeout(timeout);
	for (var h in headers) {
		con.setRequestProperty(h, headers[h]);
	}
	if (bodyText != null) {
		con.setDoOutput(true);
		var os = con.getOutputStream();
		os.write(new java.lang.String(bodyText).getBytes("UTF-8"));
		os.close();
	}
	var status = con.getResponseCode();
	var text = readAll(status >= 400 ? con.getErrorStream() : con.getInputStream());
	con.disconnect();
	return { status: status, text: text };
}

// auto: HTTP Client Connector, unless this connector has its own TLS stores.
// As far as known, the HTTP Client Connector uses the server-wide JSSE settings,
// so a per-connector client certificate needs the urlConnection transport.
function chooseTransport() {
	var t = cfg.httpTransport;
	if (t == "auto") {
		t = (sslFactory != null) ? "urlConnection" : "httpClient";
	}
	if (t == "httpClient") {
		if (sslFactory != null) {
			main.logmsg("Vault connector: httpTransport=httpClient ignores tlsKeystore/tlsTruststore, the server-wide JSSE settings apply");
		}
		httpClient = system.getConnector("ibmdi.HTTPClient");
		httpClient.initialize(null);
	} else if (t != "urlConnection") {
		throw new java.lang.Exception("Unknown httpTransport '" + cfg.httpTransport + "'. Valid: auto, httpClient, urlConnection");
	}
}

// Normal authenticated call, with one re-login on 403
function vaultCall(method, apiPath, body) {
	return vaultRequest(method, apiPath, body, { retry: true });
}

function buildSslFactory() {
	if (cfg.tlsKeystore == "" && cfg.tlsTruststore == "") {
		return null;
	}
	var keyManagers = null;
	var trustManagers = null;
	if (cfg.tlsKeystore != "") {
		var ks = loadKeystore(cfg.tlsKeystore, cfg.tlsKeystorePassword);
		var kmf = javax.net.ssl.KeyManagerFactory.getInstance(javax.net.ssl.KeyManagerFactory.getDefaultAlgorithm());
		kmf.init(ks, chars(cfg.tlsKeystorePassword));
		keyManagers = kmf.getKeyManagers();
	}
	if (cfg.tlsTruststore != "") {
		var ts = loadKeystore(cfg.tlsTruststore, cfg.tlsTruststorePassword);
		var tmf = javax.net.ssl.TrustManagerFactory.getInstance(javax.net.ssl.TrustManagerFactory.getDefaultAlgorithm());
		tmf.init(ts);
		trustManagers = tmf.getTrustManagers();
	}
	var ctx = javax.net.ssl.SSLContext.getInstance(cfg.tlsProtocol);
	ctx.init(keyManagers, trustManagers, null);
	return ctx.getSocketFactory();
}

function loadKeystore(file, password) {
	var ks = java.security.KeyStore.getInstance(cfg.tlsStoreType);
	var fis = new java.io.FileInputStream(file);
	try {
		ks.load(fis, chars(password));
	} finally {
		fis.close();
	}
	return ks;
}

function checkStatus(r, what) {
	if (r.status >= 200 && r.status < 300) {
		return;
	}
	throw new java.lang.Exception("Vault " + what + " failed: HTTP " + r.status + " " + errorText(r));
}

function errorText(r) {
	if (r.json != null && r.json.errors != null) {
		return (r.json.errors instanceof Array) ? r.json.errors.join("; ") : String(r.json.errors);
	}
	return r.text;
}

// =====================================================================
// getParam() method to simplify testing
// =====================================================================
// Test values by configuration parameter name, e.g. { roleId: "...", secretId: "..." }.
// Anything not set here falls back to the def value in vault_params.
var testParams = {};

function getParam(paramName) {
	return connector.getParam(paramName);
}


// =====================================================================
// Helpers
// =====================================================================
// Reads each setting by its configuration parameter name (param) and stores it
// under the vault_params key, which is the name the rest of the code uses (cfg.<key>).
// Empty or missing parameters fall back to def.
// Values of parameters with opt are checked against it, ignoring case, and
// stored with the spelling in opt, so the code can compare them exactly.
function loadConfig() {
	var c = vault_params.connection;
	for (var k in c) {
		var v = getParam(c[k].param);		// deployed: connector.getParam(c[k].param)
		cfg[k] = (v == null || String(v) == "") ? c[k].def : String(v);
		if (c[k].opt != null) {
			cfg[k] = checkOpt(c[k], cfg[k]);
		}
	}
	cfg.vaultUrl = cfg.vaultUrl.replace(/\/+$/, "");
	if (cfg.authMount == "") {
		cfg.authMount = cfg.authMethod;
	}
}

// A value -> its spelling in p.opt. multi: a comma-separated list of opt values.
function checkOpt(p, value) {
	var parts = p.multi ? String(value).split(",") : [String(value)];
	var out = [];
	for (var i = 0; i < parts.length; i++) {
		var v = trim(parts[i]);
		if (v == "" && p.multi) {
			continue;
		}
		var match = null;
		for (var j = 0; j < p.opt.length; j++) {
			if (p.opt[j].toLowerCase() == v.toLowerCase()) {
				match = p.opt[j];
			}
		}
		if (match == null) {
			if (p.param == "objectType") {
				return value;		// handlerFor() reports it, and names the planned types
			}
			throw new java.lang.Exception("Parameter " + p.param + ": '" + v + "' is not valid. Valid: " + p.opt.join(", ") + (p.multi ? " (a comma-separated list)" : ""));
		}
		out.push(match);
	}
	return out.join(",");
}

// Entry -> secret data. vault.* and $ attributes are not part of the secret.
function entryToData(e) {
	var data = {};
	var names = e.getAttributeNames();
	for (var i = 0; i < names.length; i++) {
		var n = String(names[i]);
		if (n.indexOf("vault.") == 0 || n.indexOf("$") == 0) {
			continue;
		}
		var att = e.getAttribute(n);
		if (att.size() > 1) {
			var arr = [];
			for (var j = 0; j < att.size(); j++) {
				arr.push(String(att.getValue(j)));
			}
			data[n] = arr;
		} else {
			data[n] = (att.size() == 0) ? "" : String(att.getValue(0));
		}
	}
	return data;
}

// Secret data -> Entry. JSON arrays become multi-valued attributes,
// nested objects are stored as JSON text.
function dataToEntry(map, out) {
	if (map == null) {
		return;
	}
	for (var k in map) {
		var v = map[k];
		if (v == null) {
			out.setAttribute(k, "");
		} else if (v instanceof Array) {
			addValues(out, k, v);
		} else if (typeof v == "object") {
			out.setAttribute(k, String(toJson(v)));
		} else {
			out.setAttribute(k, String(v));
		}
	}
}

// Copy selected fields of a Vault response object to vault.<field> attributes
function setMeta(out, map, fields) {
	for (var i = 0; map != null && i < fields.length; i++) {
		var v = map[fields[i]];
		if (v != null) {
			out.setAttribute("vault." + fields[i], String(v));
		}
	}
}

function addValues(out, name, list) {
	for (var i = 0; list != null && i < list.length; i++) {
		out.addAttributeValue(name, String(list[i]));
	}
}

function copyProps(from, to) {
	if (from == null) {
		return;
	}
	for (var k in from) {
		to[k] = from[k];
	}
}

// Every attribute and value of one entry, added to another
function copyEntry(from, to) {
	var names = from.getAttributeNames();
	for (var i = 0; i < names.length; i++) {
		var att = from.getAttribute(names[i]);
		for (var j = 0; j < att.size(); j++) {
			to.addAttributeValue(names[i], att.getValue(j));
		}
	}
}

// True when the attribute is in the entry, even with no values (= clear the field)
function isMapped(e, name) {
	return e.getAttribute(name) != null;
}

// All non-empty values of an attribute, as strings
function values(e, name) {
	var att = e.getAttribute(name);
	var list = [];
	for (var i = 0; att != null && i < att.size(); i++) {
		var v = String(att.getValue(i));
		if (v != "") {
			list.push(v);
		}
	}
	return list;
}

// Path of the target secret: vault.path in the entry (like $dn for LDAP), else the Link Criteria
function targetPath() {
	var p = opt(entry, "vault.path");
	return (p != null) ? p : pathFromSearch();
}

// Mount of the target secret: vault.mount in the entry, else the Link Criteria, else kvMount.
// Update and Delete then work on the same mount the lookup found the secret in.
function targetMount() {
	var m = opt(entry, "vault.mount");
	return (m != null) ? m : mountFromSearch();
}

// vault.path from Link Criteria. Without a vault.path criterion, the first
// criterion that is not vault.mount is taken as the path.
function pathFromSearch() {
	var fallback = null;
	if (search != null) {
		var crit = search.getCriteria();
		for (var i = 0; i < crit.size(); i++) {
			var c = crit.get(i);
			var n = String(c.name);
			if (n == "vault.path") {
				return String(c.value);
			}
			if (fallback == null && n != "vault.mount") {
				fallback = c.value;
			}
		}
	}
	if (fallback == null || String(fallback) == "") {
		throw new java.lang.Exception("Link Criteria must give the secret path, e.g. vault.path equals $secretPath");
	}
	return String(fallback);
}

// vault.mount from Link Criteria, else the kvMount parameter
function mountFromSearch() {
	var m = criteriaValue("vault.mount");
	return (m != null) ? m : cfg.kvMount;
}

// Value of the named Link Criteria attribute, or null if absent or empty
function criteriaValue(name) {
	if (search == null) {
		return null;
	}
	var crit = search.getCriteria();
	for (var i = 0; i < crit.size(); i++) {
		var c = crit.get(i);
		if (String(c.name) == name) {
			var v = c.value;
			return (v == null || String(v) == "") ? null : String(v);
		}
	}
	return null;
}

function kvApi(kind, path, mount) {
	var p = cleanPath(path);
	var segs = (p == "") ? [] : p.split("/");
	for (var i = 0; i < segs.length; i++) {
		segs[i] = encodeName(segs[i]);
	}
	return "/v1/" + cleanPath(mount) + "/" + kind + "/" + segs.join("/");
}

// One URL path segment, UTF-8 percent-encoded (space as %20, not +)
function encodeName(name) {
	return String(java.net.URLEncoder.encode(String(name), "UTF-8")).replace(/\+/g, "%20");
}

function mountOf(e) {
	return opt(e, "vault.mount") || cfg.kvMount;
}

function req(e, name) {
	var v = opt(e, name);
	if (v == null) {
		throw new java.lang.Exception("Missing required attribute: " + name);
	}
	return v;
}

function opt(e, name) {
	var v = e.getString(name);
	return (v == null || String(v) == "") ? null : String(v);
}

function parseJson(text) {
	if (text == null || text.length == 0) {
		return null;
	}
	try {
		return fromJson(text);
	} catch (ex) {
		return null;		// not JSON, e.g. an HTML error page from a proxy
	}
}

function readAll(stream) {
	if (stream == null) {
		return "";
	}
	var sc = new java.util.Scanner(stream, "UTF-8").useDelimiter("\\A");
	var t = sc.hasNext() ? String(sc.next()) : "";
	sc.close();
	return t;
}

function notYet(what, phase) {
	throw new java.lang.Exception(what + " is not implemented yet (" + phase + ")");
}

function cleanPath(p) {
	return String(p).replace(/^\/+|\/+$/g, "");
}

// path below base: apps/tdi/db below apps -> tdi/db. Base empty = the whole path.
function relativeTo(path, base) {
	var p = cleanPath(path);
	if (base == "") {
		return p;
	}
	return (p.indexOf(base + "/") == 0) ? p.substring(base.length + 1) : p;
}

function trim(s) {
	return String(s).replace(/^\s+|\s+$/g, "");
}

function contains(arr, value) {
	for (var i = 0; i < arr.length; i++) {
		if (arr[i] == value) {
			return true;
		}
	}
	return false;
}

// Property names, sorted: the script engine does not keep declaration order,
// so sorting keeps "Valid: ..." messages the same from run to run
function keysOf(obj) {
	var keys = [];
	for (var k in obj) {
		keys.push(k);
	}
	return keys.sort();
}

function chars(s) {
	return new java.lang.String(s).toCharArray();
}

function now() {
	return java.lang.System.currentTimeMillis();
}

vault_params.connection.vaultUrl.def = system.getTDIProperty("vault.url");
vault_params.connection.roleId.def = system.getTDIProperty("vault.roleId");
vault_params.connection.secretId.def = system.getTDIProperty("vault.secretId");
vault_params.connection.iteratorPath.def = system.getTDIProperty("vault.iteratorPath");

for (var pname in vault_params.connection) {
	var param = vault_params.connection[pname];
	var val = system.getTDIProperty("vault." + pname);
	if (val) {
		param.def = val;
		task.logmsg("Setting " + pname + " to " + val)
	}
}

// =====================================================================
// Vault Connector - test script
// Version 0.4.1 (draft), written for VaultConnector.js 0.4.2 (T_CONNECTOR_VERSION)
//
// History (new functionality: next 0.x, corrections: next 0.x.n)
//	2026-10-15	0.1	Server, token, KV lifecycle, edge case, list, delete and standard mode tests
//	2026-10-15	0.2	objectType policy, entity and group tests
//	2026-10-16	0.2.1	Test 81 expects the sorted "Valid: ..." list
//	2026-10-16	0.3	Iterator tests (70-77, 110-111), vault.json copies
//	2026-10-17	0.4	Versions printed at start. New tests: connector version (08), parameter checks (09),
//				CAS give-up (23), unwrap (37), wrapped secret_id tamper check (38) and login (39),
//				Link Criteria (57), vault.path in the entry (58), the other transport (62),
//				patch with vault.json (78), getNextEntry before selectEntries (79)
//	2026-10-17	0.4.1	Update and Delete run findEntry first, as TDI does (tUpdate, tDelete). Tests 53-56
//				use them, 56 shows a soft-deleted secret is no match, 58 split into match (58) and no match (59)
//
// Not tested here: cert auth (needs Vault with TLS and a client certificate)
// and vaultNamespace (Vault Enterprise/HCP only).
//
// Paste below your initialize() call in the test script.
//
// - Tests run in order and build on each other (version numbers etc.)
// - Every helper is prefixed with t so nothing collides with the
//   connector's own functions, which share the same script scope
// - Each run works in its own folder under TEST_BASE and cleans up,
//   so a failed run never leaves a secret that breaks the next one
// - Policies, entities and groups are named T_ID-<something>, so each
//   run has its own names too. The AppRole policy from setup.sh only
//   allows names starting with tdi-test-
// - The connector runs with objectType=kvSecret. The policy, entity and
//   group tests switch the objectType with tWithType(), the way a
//   connector configured with that objectType would run
// - Update and Delete go through findEntry first, the way an AssemblyLine
//   runs them: modEntry and deleteEntry are only called after a match
// - terminate() is tested last, since it revokes the token
// =====================================================================

var T_VERSION = "0.4.1";				// this test script
var T_CONNECTOR_VERSION = "0.4.2";		// the connector version these tests are written for

// Test 39 only: a wrapped AppRole secret_id, printed by setup.sh as wrappedSecretId.
// Single use, so it needs a fresh one for every run. Empty = test 39 is skipped.
var T_WRAPPED_SECRET_ID = "";

var TEST_BASE = "apps/tdi/test";			// the AppRole policy must allow this folder
var TEST_ROOT = TEST_BASE + "/run-" + now();

var P_DB	= TEST_ROOT + "/db";
var P_CTL	= TEST_ROOT + "/ctl";
var P_MULTI	= TEST_ROOT + "/multi";
var P_ODD	= TEST_ROOT + "/svc account/ø-test";
var P_MODE	= TEST_ROOT + "/modes";
var P_NONE	= TEST_ROOT + "/does-not-exist";
var P_ITER	= TEST_ROOT + "/iter";			// tree for the Iterator tests
var P_COPY	= TEST_ROOT + "/copy";			// Iterator -> AddOnly copy of P_ITER

// The Iterator test tree, relative to P_ITER. sub is both a secret and a folder.
// gone is soft-deleted after it is written.
var T_ITER_KEYS = ["a", "gone", "sub", "sub/b", "sub/deep/c", "typed"];
var T_TYPED = "{\"user\": \"svc_tdi\", \"port\": 5432, \"tls\": true, \"opts\": {\"pool\": 5, \"hosts\": [\"db01\", \"db02\"]}}";

// Names of the policy, entities and groups created by this run
var T_ID	= "tdi-test-" + now();			// the AppRole policy must allow tdi-test-*
var N_POL	= T_ID + "-pol";
var N_ALICE	= T_ID + "-alice";
var N_BOB	= T_ID + "-bob";
var N_TEAM	= T_ID + "-team";			// internal group
var N_ALL	= T_ID + "-all";			// internal group with N_TEAM as subgroup
var N_EXT	= T_ID + "-ext";			// external group
var N_NONE	= T_ID + "-does-not-exist";

var T_POLICY_V1 = "path \"secret/data/apps/tdi/test/*\" { capabilities = [\"read\"] }";
var T_POLICY_V2 = "path \"secret/data/apps/tdi/test/*\" { capabilities = [\"read\", \"list\"] }";

// =====================================================================
// TDI Script Connector beans
// =====================================================================
// In an AssemblyLine, TDI hands the Script Connector these three by name,
// and the connector functions (findEntry, putEntry, modEntry, deleteEntry,
// selectEntries, getNextEntry, queryReply) read them by those names. The
// names are fixed by TDI, so they cannot carry a prefix. The tests declare
// them here and fill them in:
//	entry	- set by tEntry() callers, tCall(), tUpdate(), tDelete() and tIterate()
//	search	- set by tSearch(): spoofed Link Criteria
//	result	- set by tSearch() and tIterate(): spoofed ConnectorResult
//		  (status 0 = no match, or end of data)
var entry = null;
var search = null;
var result = null;

// =====================================================================
// Test helpers
// =====================================================================
var tPass = 0;
var tFail = 0;

function tRun(name, fn) {
	try {
		task.logmsg("========> " + name);
		fn();
		tPass++;
		task.logmsg("PASS  " + name);
	} catch (ex) {
		tFail++;
		task.logmsg("FAIL  " + name + "\n\t" + ex);
	}
}

function tAssert(cond, msg) {
	if (!cond) {
		throw new java.lang.Exception(msg);
	}
}

function tEq(actual, expected, what) {
	tAssert(String(actual) == String(expected), what + ": expected '" + expected + "', got '" + actual + "'");
}

// Runs fn, which must throw an error containing mustContain. Returns the error text.
function tThrows(fn, mustContain) {
	try {
		fn();
	} catch (ex) {
		tAssert(String(ex).indexOf(mustContain) >= 0, "wrong error: " + ex);
		return String(ex);
	}
	throw new java.lang.Exception("expected an error containing '" + mustContain + "'");
}

// Native object -> Entry. Arrays become multi-valued attributes.
// An empty array becomes an attribute with an empty value: mapped, but no
// values, which is how an Output Map clears a field (e.g. vault.members).
function tEntry(attrs) {
	var e = system.newEntry();
	for (var k in attrs) {
		var v = attrs[k];
		if (v instanceof Array) {
			if (v.length == 0) {
				e.setAttribute(k, "");
			}
			for (var i = 0; i < v.length; i++) {
				e.addAttributeValue(k, String(v[i]));
			}
		} else {
			e.setAttribute(k, String(v));
		}
	}
	return e;
}

// CallReply: run one vault.command and return the reply entry
function tCall(command, attrs) {
	entry = tEntry(attrs || {});
	entry.setAttribute("vault.command", command);
	queryReply();
	return entry;
}

function tVal(e, name) {
	var v = e.getString(name);
	return (v == null) ? null : String(v);
}

function tVals(e, name) {
	var a = e.getAttribute(name);
	var out = [];
	for (var i = 0; a != null && i < a.size(); i++) {
		out.push(String(a.getValue(i)));
	}
	return out;
}

function tStatus(e) {
	return parseInt(tVal(e, "vault.status"), 10);
}

// Attribute names that are secret keys, i.e. not vault.*
function tSecretKeys(e) {
	var names = e.getAttributeNames();
	var keys = [];
	for (var i = 0; i < names.length; i++) {
		var n = String(names[i]);
		if (n.indexOf("vault.") != 0) {
			keys.push(n);
		}
	}
	return keys.sort();
}

function tHas(arr, value) {
	for (var i = 0; i < arr.length; i++) {
		if (arr[i] == value) {
			return true;
		}
	}
	return false;
}

// Sets the search and result beans: Link Criteria vault.path equals path
function tSearch(path) {
	tSearchCrit([{ name: "vault.path", value: path }]);
}

// Sets the search and result beans: any Link Criteria, e.g.
// [{ name: "vault.mount", value: "secret" }, { name: "vault.path", value: "apps/x" }]
function tSearchCrit(crit) {
	search = {
		getCriteria: function () {
			return {
				size: function () { return crit.length; },
				get: function (i) { return crit[i]; }
			};
		},
		getFirstCriteriaValue: function () { return (crit.length > 0) ? crit[0].value : null; }
	};
	result = {
		status: -1,
		setStatus: function (s) { this.status = s; },
		getStatus: function () { return this.status; }
	};
}

// Runs fn as if the connector were configured with objectType = type
function tWithType(type, fn) {
	var savedType = cfg.objectType;
	var savedHandler = handler;
	cfg.objectType = type;
	handler = handlerFor(type);
	try {
		fn();
	} finally {
		cfg.objectType = savedType;
		handler = savedHandler;
	}
}

// Runs fn with kvJson = true, and returns what fn returns
function tWithKvJson(fn) {
	var out = null;
	tWithCfg({ kvJson: "true" }, function () {
		out = fn();
	});
	return out;
}

// Runs fn with updateMethod = method (patch or replace)
function tWithMethod(method, fn) {
	tWithCfg({ updateMethod: method }, fn);
}

// Runs fn with the given connector parameters, e.g. { readData: "false" }
function tWithCfg(settings, fn) {
	var saved = {};
	for (var k in settings) {
		saved[k] = cfg[k];
		cfg[k] = settings[k];
	}
	try {
		fn();
	} finally {
		for (var s in saved) {
			cfg[s] = saved[s];
		}
	}
}

// The standard modes for the configured objectType, as an AssemblyLine drives them
// Lookup: returns the found entry, or null for no match (On No Match)
function tLookup(path) {
	tSearch(path);
	entry = tEntry({});
	findEntry();
	return (result.status == 0) ? null : entry;
}

// AddOnly: attrs is the Output Map result
function tAdd(attrs) {
	entry = tEntry(attrs);
	putEntry();
}

// Update, as TDI runs it: findEntry with the Link Criteria (vault.path equals path)
// first, then modEntry on a match, or putEntry on no match. attrs is the
// Output Map result. Returns true for a match.
function tUpdate(path, attrs) {
	tSearch(path);
	entry = tEntry({});
	findEntry();
	var matched = (result.status != 0);
	entry = tEntry(attrs);
	if (matched) {
		modEntry();
	} else {
		putEntry();
	}
	return matched;
}

// Delete, as TDI runs it: findEntry with the Link Criteria (vault.path equals path)
// first, then deleteEntry with the entry found. No match goes to On No Match
// and nothing is deleted. Returns true for a match.
function tDelete(path) {
	tSearch(path);
	entry = tEntry({});
	findEntry();
	var matched = (result.status != 0);
	if (matched) {
		deleteEntry();
	}
	return matched;
}

// Iterator: selectEntries once, then getNextEntry until end of data.
// settings: connector parameters for this pass. Returns the entries in order.
function tIterate(settings) {
	var found = [];
	tWithCfg(settings || {}, function () {
		result = {
			status: -1,
			setStatus: function (s) { this.status = s; },
			getStatus: function () { return this.status; }
		};
		selectEntries();
		while (true) {
			entry = tEntry({});
			result.status = -1;
			getNextEntry();
			if (result.status == 0) {
				break;
			}
			found.push(entry);
			tAssert(found.length < 100000, "the Iterator does not end");
		}
	});
	return found;
}

// One attribute of each entry, in order
function tColumn(entries, name) {
	var out = [];
	for (var i = 0; i < entries.length; i++) {
		out.push(tVal(entries[i], name));
	}
	return out;
}

// The entry in entries whose attribute name has the given value, or null
function tFind(entries, name, value) {
	for (var i = 0; i < entries.length; i++) {
		if (tVal(entries[i], name) == value) {
			return entries[i];
		}
	}
	return null;
}

// Runs fn with listNames() returning only this run's names. The AppRole
// policy can read only tdi-test-* objects, and an Iterator with readData
// reads every listed one, including the entity Vault made for this login.
function tOnlyTestNames(fn) {
	var realListNames = listNames;
	listNames = function (base, out) {
		var all = system.newEntry();
		realListNames(base, all);
		out.setAttribute("vault.status", tVal(all, "vault.status"));
		var keys = tVals(all, "vault.keys");
		for (var i = 0; i < keys.length; i++) {
			if (keys[i].indexOf(T_ID) == 0) {
				out.addAttributeValue("vault.keys", keys[i]);
			}
		}
	};
	try {
		fn();
	} finally {
		listNames = realListNames;
	}
}

// Names listed by CallReply list for an objectType, while the connector stays kvSecret
function tNames(type) {
	return tVals(tCall("list", { "vault.objectType": type }), "vault.keys");
}

// Wraps data in a single-use wrapping token (sys/wrapping/wrap, allowed by the
// default policy). Sent directly, since the wrap TTL goes in a header of its own.
function tWrap(data) {
	var headers = {
		"Accept": "application/json",
		"Content-Type": "application/json; charset=utf-8",
		"X-Vault-Token": clientToken,
		"X-Vault-Wrap-TTL": "300"
	};
	if (cfg.namespace != "") {
		headers["X-Vault-Namespace"] = cfg.namespace;
	}
	var url = cfg.vaultUrl + "/v1/sys/wrapping/wrap";
	var body = String(toJson(data));
	var res = (httpClient != null) ? sendViaHttpClient("POST", url, headers, body) : sendViaUrlConnection("POST", url, headers, body);
	tEq(res.status, 200, "sys/wrapping/wrap status (" + res.text + ")");
	return String(fromJson(res.text).wrap_info.token);
}

