});

tRun("39 wrapped secret_id: AppRole login with secretIdWrapped=true", function () {
	if (cfg.authMethod != "approle" || T_WRAPPED_SECRET_ID == "") {
		task.logmsg("\tskipped: set T_WRAPPED_SECRET_ID to a fresh wrappedSecretId from setup.sh");
		return;
	}
	var saved = { secretIdWrapped: cfg.secretIdWrapped, secretId: cfg.secretId };
	var savedSecretId = approleSecretId;
	var oldToken = clientToken;
	cfg.secretIdWrapped = "true";
	cfg.secretId = T_WRAPPED_SECRET_ID;
	approleSecretId = null;
	try {
		login();
		tAssert(clientToken != oldToken, "no new token");
		tAssert(approleSecretId != null && approleSecretId != T_WRAPPED_SECRET_ID, "secret_id was not unwrapped");
		tEq(tStatus(tCall("lookupSelf")), 200, "the new token works");
		tThrows(function () { unwrapSecretId(T_WRAPPED_SECRET_ID); }, "invalid, expired or already used");
	} finally {
		copyProps(saved, cfg);
		approleSecretId = savedSecretId;
		login();		// back to the plain secret_id
	}
});

