tRun("56 Delete (permanent): a soft-deleted secret is no match, a live one is removed with all versions", function () {
	tWithCfg({ deleteMode: "permanent" }, function () {
		// Lookup does not find a soft-deleted secret, so Delete mode never reaches it
		tAssert(!tDelete(P_MODE), "the soft-deleted secret matched");
		tEq(tStatus(tCall("metadataRead", { "vault.path": P_MODE })), 200, "metadata still there");

		// Write it again, and Delete mode can remove it for good
		tCall("write", { "vault.path": P_MODE, username: "svc_hr", password: "Hr-Pw-4" });
		tAssert(tDelete(P_MODE), "no match");
	});
	tEq(tStatus(tCall("metadataRead", { "vault.path": P_MODE })), 404, "metadata after delete");
});

tRun("57 Link Criteria: vault.mount, path by another name, and no path at all", function () {
	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }, { name: "vault.path", value: P_MULTI }]);
	entry = tEntry({});
	findEntry();
	tAssert(result.status != 0, "vault.mount + vault.path: no match");
	tEq(tVal(entry, "vault.mount"), cfg.kvMount, "vault.mount");

	// Without vault.path, the first criterion that is not vault.mount is the path
	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }, { name: "secretPath", value: P_MULTI }]);
	entry = tEntry({});
	findEntry();
	tAssert(result.status != 0, "path under another name: no match");
	tEq(tVal(entry, "vault.path"), P_MULTI, "vault.path");

	tSearchCrit([{ name: "vault.mount", value: cfg.kvMount }]);
	entry = tEntry({});
	tThrows(findEntry, "Link Criteria must give the secret path");
});

